/* TỰ SINH bởi tools/build-zh-game.mjs từ data/curriculum (giáo trình HSK của app ATLAS), đừng sửa tay. */
var G = window.G || (window.G = {});
G.ROOMS = G.ROOMS || {};
G.ROOMS["zh-l025"] = {"id":"zh-l025","lang":"zh","level":2,"no":25,"teacher":"wang","title":"HSK2 · Bài 25 · 你身体怎么样？ Sức khoẻ","intro":["你身体怎么样？","Bài 25: Nói về sức khoẻ và cảm giác, dùng 觉得 để nêu ý kiến, phân biệt 非常 với 很. Bấm 1 · Học để bắt đầu."],"introPy":"Nǐ shēntǐ zěnmeyàng?","gram":{"t":"觉得 — nêu ý kiến, theo sau là cả một câu","b":"Chủ ngữ + 觉得 + [một câu hoàn chỉnh]","d":"Khác các động từ thường chỉ nhận một danh từ, sau 觉得 phải là một mệnh đề có đủ chủ ngữ và vị ngữ. Nói 我觉得很好 cũng được vì chủ ngữ của vế sau được hiểu ngầm.","ex":[["我觉得这个菜很好吃。","Tôi thấy món này rất ngon.","Wǒ juéde zhège cài hěn hǎochī."],["你觉得怎么样？","Bạn thấy thế nào?","Nǐ juéde zěnmeyàng?"],["我不觉得累。","Tôi không thấy mệt.","Wǒ bù juéde lèi."]]},"grams":[{"t":"觉得 — nêu ý kiến, theo sau là cả một câu","b":"Chủ ngữ + 觉得 + [một câu hoàn chỉnh]","d":"Khác các động từ thường chỉ nhận một danh từ, sau 觉得 phải là một mệnh đề có đủ chủ ngữ và vị ngữ. Nói 我觉得很好 cũng được vì chủ ngữ của vế sau được hiểu ngầm.","ex":[["我觉得这个菜很好吃。","Tôi thấy món này rất ngon.","Wǒ juéde zhège cài hěn hǎochī."],["你觉得怎么样？","Bạn thấy thế nào?","Nǐ juéde zěnmeyàng?"],["我不觉得累。","Tôi không thấy mệt.","Wǒ bù juéde lèi."]]},{"t":"很 và 非常 — hai mức độ khác hẳn nhau","b":"很 = từ đệm bắt buộc · 非常 = thật sự rất","d":"Đây là điểm người Việt hay hiểu sai. 我很好 chỉ nghĩa là \"tôi khoẻ\" (bình thường). Muốn nói \"tôi RẤT khoẻ\" thì phải dùng 非常好. Nhớ: 很 nhạt, 非常 đậm.","ex":[["我很累。","Tôi mệt.","Wǒ hěn lèi."],["我非常累。","Tôi mệt lả người.","Wǒ fēicháng lèi."]]},{"t":"一下 và 一点儿 — làm nhẹ giọng cho lịch sự","b":"Động từ + 一下 · Tính từ + 一点儿","d":"Thêm 一下 sau động từ nghĩa là \"làm một chút\", nghe mềm và lịch sự hơn nhiều. Với tính từ thì dùng 一点儿.","ex":[["你休息一下吧。","Bạn nghỉ một chút đi.","Nǐ xiūxi yíxià ba."],["请说慢一点儿。","Xin nói chậm một chút.","Qǐng shuō màn yìdiǎnr."]]}],"items":[{"zh":"身体","py":"shēntǐ","vi":"cơ thể, sức khoẻ","hv":"thân thể","note":"Chính là \"thân thể\" tiếng Việt. Hỏi thăm sức khoẻ: 你身体怎么样？","ex":"你身体怎么样？","exPy":"Nǐ shēntǐ zěnmeyàng?","exVi":"Sức khoẻ bạn thế nào?","w":"你 身体 怎么样？"},{"zh":"眼睛","py":"yǎnjing","vi":"con mắt","hv":"nhãn tinh","note":"Cả hai chữ đều có bộ 目 (mắt). Tiếng Việt: \"nhãn khoa\", \"nhãn cầu\". Chữ thứ hai đọc nhẹ.","ex":"她的眼睛又大又漂亮。","exPy":"Tā de yǎnjing yòu dà yòu piàoliang.","exVi":"Mắt cô ấy vừa to vừa đẹp.","w":"她 的 眼睛 又 大 又 漂亮。"},{"zh":"生病","py":"shēngbìng","vi":"bị bệnh, ốm","hv":"sinh bệnh","note":"生 (sinh ra) + 病 (bệnh). Là ĐỘNG TỪ nên nói 我生病了, không nói 我是生病.","ex":"我昨天生病了。","exPy":"Wǒ zuótiān shēngbìng le.","exVi":"Hôm qua tôi bị ốm.","w":"我 昨天 生病 了。"},{"zh":"药","py":"yào","vi":"thuốc","hv":"dược","note":"Bộ 艹 (cỏ cây) trên đầu — thuốc xưa làm từ cây cỏ. Tiếng Việt: \"dược sĩ\", \"đông dược\".","ex":"你吃药了吗？","exPy":"Nǐ chī yào le ma?","exVi":"Bạn uống thuốc chưa?","w":"你 吃 药 了 吗？"},{"zh":"累","py":"lèi","vi":"mệt","hv":"luy","note":"田 (ruộng) trên 糸 (sợi tơ) — làm ruộng dệt vải thì mệt. Khi tả trạng thái, câu kể thường có 很 đứng trước: 我很累. Nói 累了, 累死了 cũng rất tự nhiên.","ex":"我今天非常累。","exPy":"Wǒ jīntiān fēicháng lèi.","exVi":"Hôm nay tôi mệt lả.","w":"我 今天 非常 累。"},{"zh":"休息","py":"xiūxi","vi":"nghỉ ngơi","hv":"hưu tức","note":"休 = 亻(người) dựa vào 木 (cây) — người tựa gốc cây nghỉ. Tiếng Việt: \"hưu trí\", \"nghỉ hưu\".","ex":"你休息一下吧。","exPy":"Nǐ xiūxi yíxià ba.","exVi":"Bạn nghỉ một chút đi.","w":"你 休息 一下 吧。"},{"zh":"觉得","py":"juéde","vi":"cảm thấy, thấy rằng","hv":"giác đắc","note":"Dùng để nêu ý kiến cá nhân, giống \"tôi thấy…\" tiếng Việt. Sau 觉得 là CẢ MỘT CÂU.","ex":"我觉得这个药很好。","exPy":"Wǒ juéde zhège yào hěn hǎo.","exVi":"Tôi thấy thuốc này tốt.","w":"我 觉得 这个 药 很 好。"},{"zh":"非常","py":"fēicháng","vi":"vô cùng, cực kỳ","hv":"phi thường","note":"Chính là \"phi thường\" tiếng Việt. Mạnh hơn 很 rất nhiều — đây mới thật sự là \"rất\".","ex":"我非常高兴。","exPy":"Wǒ fēicháng gāoxìng.","exVi":"Tôi vô cùng vui.","w":"我 非常 高兴。"},{"zh":"快","py":"kuài","vi":"nhanh","hv":"khoái","note":"Bộ 忄 (tim) — vốn nghĩa là vui, sau thành \"nhanh\". Tiếng Việt: \"khoái lạc\", \"sảng khoái\".","ex":"他吃饭很快。","exPy":"Tā chīfàn hěn kuài.","exVi":"Anh ấy ăn cơm rất nhanh.","w":"他 吃 饭 很 快。"},{"zh":"慢","py":"màn","vi":"chậm","hv":"mạn","note":"Cũng có bộ 忄. Tiếng Việt: \"mạn tính\" (bệnh tiến triển chậm). 慢慢来 = từ từ thôi.","ex":"请说慢一点儿，我听不懂。","exPy":"Qǐng shuō màn yìdiǎnr, wǒ tīng bu dǒng.","exVi":"Xin nói chậm chút, tôi nghe không hiểu.","w":"请 说 慢 一点儿， 我 听 不 懂。"}],"newChars":["身","体","眼","睛","病","药","累","休","非","常","慢"],"outro":"很好！Xong bài 25."};
G.ROOMS["zh-l027"] = {"id":"zh-l027","lang":"zh","level":2,"no":27,"teacher":"wang","title":"HSK2 · Bài 27 · 在教室里 Trong lớp học","intro":["老师在教室里吗？","Bài 27: Hỏi bài, nói hiểu hay không hiểu, và khai thác kho từ Hán Việt về học hành. Bấm 1 · Học để bắt đầu."],"introPy":"Lǎoshī zài jiàoshì lǐ ma?","gram":{"t":"Bốn câu sống còn trong lớp học","b":"我不懂 · 请再说一次 · 这是什么意思？· 我有一个问题","d":"Học thuộc bốn câu này trước mọi thứ khác. Không hiểu mà im lặng là cách học chậm nhất.","ex":[["老师，我有一个问题。","Thưa thầy, em có một câu hỏi.","Lǎoshī, wǒ yǒu yí ge wèntí."],["这个字是什么意思？","Chữ này nghĩa là gì?","Zhège zì shì shénme yìsi?"],["对不起，我不懂。","Xin lỗi, em không hiểu.","Duìbuqǐ, wǒ bù dǒng."]]},"grams":[{"t":"Bốn câu sống còn trong lớp học","b":"我不懂 · 请再说一次 · 这是什么意思？· 我有一个问题","d":"Học thuộc bốn câu này trước mọi thứ khác. Không hiểu mà im lặng là cách học chậm nhất.","ex":[["老师，我有一个问题。","Thưa thầy, em có một câu hỏi.","Lǎoshī, wǒ yǒu yí ge wèntí."],["这个字是什么意思？","Chữ này nghĩa là gì?","Zhège zì shì shénme yìsi?"],["对不起，我不懂。","Xin lỗi, em không hiểu.","Duìbuqǐ, wǒ bù dǒng."]]},{"t":"Bổ ngữ kết quả với 懂","b":"听懂 = nghe HIỂU · 看懂 = đọc HIỂU","d":"Ghép động từ giác quan với 懂 để nói rõ có đạt kết quả hay không. Phủ định chèn 不 vào giữa: 听不懂 (nghe mà không hiểu), khẳng định là 听得懂.","ex":[["我听不懂。","Tôi nghe không hiểu.","Wǒ tīng bu dǒng."],["这本书我看得懂。","Quyển sách này tôi đọc hiểu được.","Zhè běn shū wǒ kàn de dǒng."]]},{"t":"Kho từ Hán Việt về học hành — học một biết mười","b":"问题 vấn đề · 考试 khảo thí · 题 đề · 意思 ý tứ · 教室 giáo thất","d":"Cả bài này gần như là tiếng Việt viết bằng chữ Hán. Đây chính là lợi thế mà người học tiếng Anh không bao giờ có được — hãy tận dụng triệt để: gặp từ mới, thử đọc âm Hán Việt trước khi tra nghĩa.","ex":[["问题","vấn đề","wèntí"],["考试","khảo thí → kỳ thi","kǎoshì"],["注意","chú ý","zhùyì"]]}],"items":[{"zh":"课","py":"kè","vi":"bài học, tiết học","hv":"khoá","note":"Bộ 讠 (lời nói). Tiếng Việt: \"khoá học\", \"giáo khoa\". 上课 = vào học, 下课 = tan học.","ex":"我们几点上课？","exPy":"Wǒmen jǐ diǎn shàngkè?","exVi":"Mấy giờ chúng ta vào học?","w":"我们 几 点 上课？"},{"zh":"教室","py":"jiàoshì","vi":"phòng học, lớp học","hv":"giáo thất","note":"教 (dạy) + 室 (phòng, bộ 宀 mái nhà). Tiếng Việt: \"giáo dục\", \"phòng thất\".","ex":"老师在教室里吗？","exPy":"Lǎoshī zài jiàoshì lǐ ma?","exVi":"Thầy có ở trong lớp không?","w":"老师 在 教室 里 吗？"},{"zh":"考试","py":"kǎoshì","vi":"thi, kỳ thi","hv":"khảo thí","note":"Chính là \"khảo thí\" tiếng Việt. Vừa là danh từ vừa là động từ: 明天考试 = mai thi.","ex":"我们明天有考试。","exPy":"Wǒmen míngtiān yǒu kǎoshì.","exVi":"Mai chúng tôi có bài kiểm tra.","w":"我们 明天 有 考试。"},{"zh":"题","py":"tí","vi":"câu hỏi, bài tập, đề","hv":"đề","note":"Đúng là chữ \"đề\" trong \"đề bài\", \"chủ đề\" của tiếng Việt.","ex":"这个题太难了。","exPy":"Zhège tí tài nán le.","exVi":"Bài này khó quá.","w":"这个 题 太 难 了。"},{"zh":"问题","py":"wèntí","vi":"câu hỏi; vấn đề","hv":"vấn đề","note":"Chính là \"vấn đề\" tiếng Việt. Vừa nghĩa là câu hỏi, vừa nghĩa là rắc rối — y hệt tiếng Việt.","ex":"我有一个问题想问你。","exPy":"Wǒ yǒu yí ge wèntí xiǎng wèn nǐ.","exVi":"Tôi có một câu muốn hỏi bạn.","w":"我 有 一 个 问题 想 问 你。"},{"zh":"问","py":"wèn","vi":"hỏi","hv":"vấn","note":"口 (miệng) nằm trong 门 (cửa) — thò đầu qua cửa hỏi. Tiếng Việt: \"phỏng vấn\", \"tư vấn\".","ex":"我想问老师。","exPy":"Wǒ xiǎng wèn lǎoshī.","exVi":"Tôi muốn hỏi thầy.","w":"我 想 问 老师。"},{"zh":"懂","py":"dǒng","vi":"hiểu","hv":"đổng","note":"Bộ 忄 (tim) — hiểu là chuyện của lòng. Rất hay dùng: 听懂 (nghe hiểu), 看懂 (đọc hiểu).","ex":"对不起，我听不懂。","exPy":"Duìbuqǐ, wǒ tīng bu dǒng.","exVi":"Xin lỗi, tôi nghe không hiểu.","w":"对不起， 我 听 不 懂。"},{"zh":"铅笔","py":"qiānbǐ","vi":"bút chì","hv":"duyên bút","note":"铅 (chì, bộ 钅 kim loại) + 笔 (bút, bộ 竹 tre). Chữ 笔 = 竹 trên 毛 (lông) — đúng là cây bút lông!","ex":"请用铅笔写。","exPy":"Qǐng yòng qiānbǐ xiě.","exVi":"Xin viết bằng bút chì.","w":"请 用 铅笔 写。"},{"zh":"意思","py":"yìsi","vi":"ý nghĩa","hv":"ý tứ","note":"Cả hai chữ đều có bộ 心. Tiếng Việt: \"ý tứ\", \"ý nghĩa\". 有意思 = thú vị.","ex":"这个字是什么意思？","exPy":"Zhège zì shì shénme yìsi?","exVi":"Chữ này nghĩa là gì?","w":"这个 字 是 什么 意思？"},{"zh":"对","py":"duì","vi":"đúng; đối với","hv":"đối","note":"Tiếng Việt: \"đối đáp\", \"đối tượng\". Đáp \"đúng rồi\" là 对了.","ex":"对，你说得对。","exPy":"Duì, nǐ shuō de duì.","exVi":"Đúng, bạn nói đúng.","w":"对， 你 说 得 对。"}],"newChars":["课","教","室","考","试","题","问","懂","铅","笔","意","思"],"outro":"很好！Xong bài 27."};
G.ROOMS["zh-l028"] = {"id":"zh-l028","lang":"zh","level":2,"no":28,"teacher":"wang","title":"HSK2 · Bài 28 · 在公司 Ở công ty","intro":["你在哪儿上班？","Bài 28: Nói về công việc, dùng câu hai tân ngữ (告诉, 给) và câu nhờ vả với 让. Bấm 1 · Học để bắt đầu."],"introPy":"Nǐ zài nǎr shàngbān?","gram":{"t":"Động từ nhận HAI tân ngữ","b":"告诉 / 给 / 教 + người + vật","d":"Một số động từ nhận liền hai tân ngữ: người nhận đứng TRƯỚC, vật đứng SAU. Trật tự này giống tiếng Việt \"đưa TÔI quyển sách\", nên rất dễ với người Việt.","ex":[["他给我一本书。","Anh ấy đưa tôi một quyển sách.","Tā gěi wǒ yì běn shū."],["请告诉我你的名字。","Xin cho tôi biết tên bạn.","Qǐng gàosu wǒ nǐ de míngzi."],["老师教我们汉语。","Thầy dạy chúng tôi tiếng Trung.","Lǎoshī jiāo wǒmen Hànyǔ."]]},"grams":[{"t":"Động từ nhận HAI tân ngữ","b":"告诉 / 给 / 教 + người + vật","d":"Một số động từ nhận liền hai tân ngữ: người nhận đứng TRƯỚC, vật đứng SAU. Trật tự này giống tiếng Việt \"đưa TÔI quyển sách\", nên rất dễ với người Việt.","ex":[["他给我一本书。","Anh ấy đưa tôi một quyển sách.","Tā gěi wǒ yì běn shū."],["请告诉我你的名字。","Xin cho tôi biết tên bạn.","Qǐng gàosu wǒ nǐ de míngzi."],["老师教我们汉语。","Thầy dạy chúng tôi tiếng Trung.","Lǎoshī jiāo wǒmen Hànyǔ."]]},{"t":"让 — bảo ai đó làm việc gì","b":"A + 让 + B + động từ","d":"Câu có hai tầng: A khiến B làm việc. Chú ý 让 đứng trước NGƯỜI, rồi mới tới việc. Phủ định đặt 不 trước 让: 妈妈不让我去.","ex":[["妈妈让我早点儿回家。","Mẹ bảo tôi về nhà sớm chút.","Māma ràng wǒ zǎo diǎnr huí jiā."],["老板不让我们休息。","Sếp không cho chúng tôi nghỉ.","Lǎobǎn bú ràng wǒmen xiūxi."]]},{"t":"帮 và 帮助 — nhờ giúp","b":"帮 + người + động từ","d":"Khi nhờ ai làm việc gì thì dùng 帮 (không cần 助): 帮我看一下 (xem giúp tôi chút). Còn 帮助 hay dùng như danh từ hoặc trong câu trang trọng.","ex":[["你能帮我一下吗？","Bạn giúp tôi một chút được không?","Nǐ néng bāng wǒ yíxià ma?"],["谢谢你的帮助。","Cảm ơn sự giúp đỡ của bạn.","Xièxie nǐ de bāngzhù."]]}],"items":[{"zh":"公司","py":"gōngsī","vi":"công ty","hv":"công ty","note":"Chính là \"công ty\" tiếng Việt — mượn thẳng từ chữ Hán này.","ex":"我在一家公司上班。","exPy":"Wǒ zài yì jiā gōngsī shàngbān.","exVi":"Tôi làm ở một công ty.","w":"我 在 一 家 公司 上班。"},{"zh":"上班","py":"shàngbān","vi":"đi làm","hv":"thượng ban","note":"上 (lên) + 班 (ca, lớp). Đối lại là 下班 (tan làm) — giống cặp 上课 / 下课.","ex":"你在哪儿上班？","exPy":"Nǐ zài nǎr shàngbān?","exVi":"Bạn làm việc ở đâu?","w":"你 在 哪儿 上班？"},{"zh":"忙","py":"máng","vi":"bận","hv":"mang","note":"Bộ 忄 (tim) + 亡 (mất) — bận đến mức mất cả tâm trí. Cách ghép chữ rất gợi.","ex":"我今天很忙，有很多事情。","exPy":"Wǒ jīntiān hěn máng, yǒu hěn duō shìqing.","exVi":"Hôm nay tôi rất bận, có nhiều việc.","w":"我 今天 很 忙， 有 很 多 事情。"},{"zh":"事情","py":"shìqing","vi":"việc, chuyện","hv":"sự tình","note":"Chính là \"sự tình\" tiếng Việt. Nói tắt chỉ dùng 事 cũng được: 我有事 (tôi có việc).","ex":"我有一件事情。","exPy":"Wǒ yǒu yí jiàn shìqing.","exVi":"Tôi có một việc.","w":"我 有 一 件 事情。"},{"zh":"帮助","py":"bāngzhù","vi":"giúp đỡ","hv":"bang trợ","note":"助 = \"trợ\" trong \"trợ giúp\", \"hỗ trợ\". Nói tắt là 帮: 帮我一下 (giúp tôi chút).","ex":"谢谢你的帮助。","exPy":"Xièxie nǐ de bāngzhù.","exVi":"Cảm ơn sự giúp đỡ của bạn.","w":"谢谢 你 的 帮助。"},{"zh":"介绍","py":"jièshào","vi":"giới thiệu","hv":"giới thiệu","note":"Chính là \"giới thiệu\" tiếng Việt. Cả hai chữ đều có bộ 纟 hoặc liên quan tới sợi dây nối.","ex":"我介绍一下，这是我的同事。","exPy":"Wǒ jièshào yíxià, zhè shì wǒ de tóngshì.","exVi":"Tôi xin giới thiệu, đây là đồng nghiệp của tôi.","w":"我 介绍 一下， 这 是 我 的 同事。"},{"zh":"告诉","py":"gàosu","vi":"nói cho biết, bảo","hv":"cáo tố","note":"Tiếng Việt: \"cáo\" trong \"báo cáo\", \"tố\" trong \"tố cáo\". Nhận HAI tân ngữ: 告诉 ai cái gì.","ex":"请告诉我你的电话号码。","exPy":"Qǐng gàosu wǒ nǐ de diànhuà hàomǎ.","exVi":"Xin cho tôi số điện thoại của bạn.","w":"请 告诉 我 你 的 电话 号码。"},{"zh":"给","py":"gěi","vi":"cho, đưa; cho ai đó","hv":"cấp","note":"Bộ 纟. Tiếng Việt: \"cung cấp\", \"cấp phát\". Vừa là động từ (đưa) vừa là giới từ (cho ai).","ex":"他给我打电话了。","exPy":"Tā gěi wǒ dǎ diànhuà le.","exVi":"Anh ấy gọi điện cho tôi rồi.","w":"他 给 我 打电话 了。"},{"zh":"让","py":"ràng","vi":"để cho, bảo ai làm gì","hv":"nhượng","note":"Bộ 讠 (lời nói). Tiếng Việt: \"nhượng bộ\", \"nhường\". Dùng để sai bảo hoặc cho phép.","ex":"老板让我明天来。","exPy":"Lǎobǎn ràng wǒ míngtiān lái.","exVi":"Sếp bảo tôi mai đến.","w":"老板 让 我 明天 来。"},{"zh":"准备","py":"zhǔnbèi","vi":"chuẩn bị; định làm","hv":"chuẩn bị","note":"Chính là \"chuẩn bị\" tiếng Việt. Còn nghĩa \"dự định\": 我准备去中国.","ex":"我准备去中国工作。","exPy":"Wǒ zhǔnbèi qù Zhōngguó gōngzuò.","exVi":"Tôi định sang Trung Quốc làm việc.","w":"我 准备 去 中国 工作。"}],"newChars":["公","司","班","忙","事","帮","助","介","绍","告","诉","给","让","准","备"],"outro":"很好！Xong bài 28."};
G.ROOMS["zh-l032"] = {"id":"zh-l032","lang":"zh","level":2,"no":32,"teacher":"wang","title":"HSK2 · Bài 32 · 怎么走？ Hỏi đường","intro":["请问，火车站怎么走？","Bài 32: Hỏi đường và nói khoảng cách, dùng 离 để đo xa gần và 往 để chỉ hướng. Bấm 1 · Học để bắt đầu."],"introPy":"Qǐngwèn, huǒchēzhàn zěnme zǒu?","gram":{"t":"离 — đo khoảng cách giữa hai nơi","b":"A + 离 + B + 远 / 近","d":"Mẫu câu cố định để nói xa gần. Chú ý KHÔNG dùng 从 ở đây: nói 从我家到学校很近 cũng được nhưng dài dòng, người bản xứ dùng 离 gọn hơn.","ex":[["我家离学校很近。","Nhà tôi gần trường.","Wǒ jiā lí xuéxiào hěn jìn."],["机场离这儿远吗？","Sân bay có xa đây không?","Jīchǎng lí zhèr yuǎn ma?"],["离考试还有三天。","Còn ba ngày nữa là thi.","Lí kǎoshì hái yǒu sān tiān."]]},"grams":[{"t":"离 — đo khoảng cách giữa hai nơi","b":"A + 离 + B + 远 / 近","d":"Mẫu câu cố định để nói xa gần. Chú ý KHÔNG dùng 从 ở đây: nói 从我家到学校很近 cũng được nhưng dài dòng, người bản xứ dùng 离 gọn hơn.","ex":[["我家离学校很近。","Nhà tôi gần trường.","Wǒ jiā lí xuéxiào hěn jìn."],["机场离这儿远吗？","Sân bay có xa đây không?","Jīchǎng lí zhèr yuǎn ma?"],["离考试还有三天。","Còn ba ngày nữa là thi.","Lí kǎoshì hái yǒu sān tiān."]]},{"t":"往 + hướng + 走 — chỉ đường","b":"往 + 前/后/左/右 + 走","d":"Bộ ba câu chỉ đường cơ bản. 往前走 đi thẳng, 往左走 rẽ trái, 往右走 rẽ phải. Học thuộc là đi đâu cũng hỏi được đường.","ex":[["往前走五分钟。","Đi thẳng năm phút.","Wǎng qián zǒu wǔ fēnzhōng."],["往右走，就到了。","Rẽ phải là tới ngay.","Wǎng yòu zǒu, jiù dào le."]]},{"t":"Phương tiện: 坐 hay 骑?","b":"坐 cho xe có chỗ ngồi · 骑 qí cho thứ phải dạng chân","d":"坐公共汽车, 坐火车, 坐飞机 (ngồi). Nhưng xe đạp và xe máy thì 骑自行车, 骑摩托车 (cưỡi) — giống tiếng Việt nói \"cưỡi ngựa\".","ex":[["我坐公共汽车去。","Tôi đi bằng xe buýt.","Wǒ zuò gōnggòng qìchē qù."],["他骑自行车上班。","Anh ấy đạp xe đi làm.","Tā qí zìxíngchē shàngbān."]]}],"items":[{"zh":"火车站","py":"huǒchēzhàn","vi":"ga tàu hoả","hv":"hoả xa trạm","note":"火车 chính là \"hoả xa\" — xe chạy bằng lửa, tức tàu hoả. 站 là \"trạm\". Ghép lại quá dễ nhớ với người Việt.","ex":"请问，火车站怎么走？","exPy":"Qǐngwèn, huǒchēzhàn zěnme zǒu?","exVi":"Xin hỏi, ga tàu đi thế nào ạ?","w":"请问， 火车站 怎么 走？"},{"zh":"机场","py":"jīchǎng","vi":"sân bay","hv":"cơ trường","note":"机 (máy, viết tắt của 飞机 phi cơ) + 场 (bãi, sân). Nghĩa đen: bãi đỗ máy bay.","ex":"这儿离机场远吗？","exPy":"Zhèr lí jīchǎng yuǎn ma?","exVi":"Từ đây đến sân bay có xa không?","w":"这儿 离 机场 远 吗？"},{"zh":"公共汽车","py":"gōnggòng qìchē","vi":"xe buýt","hv":"công cộng khí xa","note":"公共 chính là \"công cộng\", 汽车 là \"khí xa\" (xe chạy bằng hơi) = ô tô. Nói tắt là 公交车.","ex":"我每天坐公共汽车上班。","exPy":"Wǒ měi tiān zuò gōnggòng qìchē shàngbān.","exVi":"Ngày nào tôi cũng đi làm bằng xe buýt.","w":"我 每 天 坐 公共汽车 上班。"},{"zh":"自行车","py":"zìxíngchē","vi":"xe đạp","hv":"tự hành xa","note":"自行 = \"tự hành\" (tự đi) + 车 (xe). Xe tự chạy bằng sức mình — cách gọi rất logic.","ex":"他骑自行车去学校。","exPy":"Tā qí zìxíngchē qù xuéxiào.","exVi":"Cậu ấy đạp xe đến trường.","w":"他 骑 自行车 去 学校。"},{"zh":"路","py":"lù","vi":"đường","hv":"lộ","note":"Bộ ⻊ (chân) bên trái. Tiếng Việt: \"lộ trình\", \"đại lộ\", \"đường lộ\".","ex":"这条路很长。","exPy":"Zhè tiáo lù hěn cháng.","exVi":"Con đường này rất dài.","w":"这 条 路 很 长。"},{"zh":"远","py":"yuǎn","vi":"xa","hv":"viễn","note":"Bộ 辶 (đi đường). Tiếng Việt: \"viễn thông\", \"viễn cảnh\", \"vĩnh viễn\".","ex":"不远，很近。","exPy":"Bù yuǎn, hěn jìn.","exVi":"Không xa, rất gần.","w":"不 远， 很 近。"},{"zh":"近","py":"jìn","vi":"gần","hv":"cận","note":"Cũng có bộ 辶. Tiếng Việt: \"cận thị\", \"lân cận\", \"cận cảnh\".","ex":"我家离学校很近。","exPy":"Wǒ jiā lí xuéxiào hěn jìn.","exVi":"Nhà tôi gần trường.","w":"我 家 离 学校 很 近。"},{"zh":"离","py":"lí","vi":"cách (khoảng cách)","hv":"ly","note":"Tiếng Việt: \"ly biệt\", \"cách ly\", \"chia ly\". Chuyên dùng để đo khoảng cách giữa hai điểm.","ex":"我家离公司很远。","exPy":"Wǒ jiā lí gōngsī hěn yuǎn.","exVi":"Nhà tôi xa công ty lắm.","w":"我 家 离 公司 很 远。"},{"zh":"往","py":"wǎng","vi":"về phía, hướng về","hv":"vãng","note":"Bộ 彳 (bước chân trái). Tiếng Việt: \"vãng lai\", \"dĩ vãng\". Chỉ hướng di chuyển.","ex":"往前走，然后往左走。","exPy":"Wǎng qián zǒu, ránhòu wǎng zuǒ zǒu.","exVi":"Đi thẳng, rồi rẽ trái.","w":"往 前 走， 然后 往 左 走。"},{"zh":"走","py":"zǒu","vi":"đi bộ; rời đi","hv":"tẩu","note":"Bộ thủ đã học. Khác 去: 走 nhấn vào HÀNH ĐỘNG đi/rời đi, 去 nhấn vào ĐÍCH ĐẾN.","ex":"我们走吧，快到了。","exPy":"Wǒmen zǒu ba, kuài dào le.","exVi":"Đi thôi, sắp tới rồi.","w":"我们 走 吧， 快 到 了。"}],"newChars":["火","站","共","汽","近","离","往","走"],"outro":"很好！Xong bài 32."};
G.ROOMS["zh-l033"] = {"id":"zh-l033","lang":"zh","level":2,"no":33,"teacher":"wang","title":"HSK2 · Bài 33 · 在宾馆 Ở khách sạn","intro":["我住在这个宾馆。","Bài 33: Chỉ vị trí trái phải, vào ra, và học 过 để kể chuyện \"đã từng\". Bấm 1 · Học để bắt đầu."],"introPy":"Wǒ zhù zài zhège bīnguǎn.","gram":{"t":"过 — kinh nghiệm \"đã từng làm\"","b":"Động từ + 过 (đọc nhẹ: guo)","d":"Đây là điểm ngữ pháp quan trọng nhất của HSK 2. 过 KHÔNG phải quá khứ mà là KINH NGHIỆM: từng làm ít nhất một lần trong đời. So sánh: 我吃了 (tôi ăn rồi — vừa xong) và 我吃过 (tôi từng ăn — biết mùi vị rồi).","ex":[["我去过中国。","Tôi từng đi Trung Quốc.","Wǒ qù guo Zhōngguó."],["你吃过中国菜吗？","Bạn từng ăn món Trung Quốc chưa?","Nǐ chī guo Zhōngguó cài ma?"],["我没去过日本。","Tôi chưa từng đi Nhật.","Wǒ méi qù guo Rìběn."]]},"grams":[{"t":"过 — kinh nghiệm \"đã từng làm\"","b":"Động từ + 过 (đọc nhẹ: guo)","d":"Đây là điểm ngữ pháp quan trọng nhất của HSK 2. 过 KHÔNG phải quá khứ mà là KINH NGHIỆM: từng làm ít nhất một lần trong đời. So sánh: 我吃了 (tôi ăn rồi — vừa xong) và 我吃过 (tôi từng ăn — biết mùi vị rồi).","ex":[["我去过中国。","Tôi từng đi Trung Quốc.","Wǒ qù guo Zhōngguó."],["你吃过中国菜吗？","Bạn từng ăn món Trung Quốc chưa?","Nǐ chī guo Zhōngguó cài ma?"],["我没去过日本。","Tôi chưa từng đi Nhật.","Wǒ méi qù guo Rìběn."]]},{"t":"Phủ định của 过 dùng 没, và GIỮ LẠI 过","b":"没 + động từ + 过","d":"Khác hẳn 了 (phủ định thì phải bỏ 了). Với 过 thì 过 vẫn ở nguyên: 我没去过 là ĐÚNG. Nói 我不去过 là sai.","ex":[["我没看过这个电影。","Tôi chưa xem phim này bao giờ.","Wǒ méi kàn guo zhège diànyǐng."],["他没来过我家。","Anh ấy chưa từng đến nhà tôi.","Tā méi lái guo wǒ jiā."]]},{"t":"Từ chỉ vị trí luôn đứng SAU danh từ","b":"Danh từ + 左边 / 右边 / 旁边 / 外边","d":"Nhắc lại quy tắc bài 11, giờ áp dụng cho các hướng mới. Tiếng Việt nói \"bên trái NHÀ\", tiếng Trung nói \"NHÀ bên trái\" (房子左边).","ex":[["宾馆旁边有一家饭馆。","Cạnh khách sạn có một quán ăn.","Bīnguǎn pángbiān yǒu yì jiā fànguǎn."],["学校左边是医院。","Bên trái trường là bệnh viện.","Xuéxiào zuǒbiān shì yīyuàn."]]}],"items":[{"zh":"左边","py":"zuǒbiān","vi":"bên trái","hv":"tả biên","note":"Tiếng Việt: \"tả ngạn\" (bờ trái sông), \"phe tả\". 边 = \"biên\" trong \"biên giới\".","ex":"书在左边。","exPy":"Shū zài zuǒbiān.","exVi":"Sách ở bên trái.","w":"书 在 左边。"},{"zh":"右边","py":"yòubiān","vi":"bên phải","hv":"hữu biên","note":"Tiếng Việt: \"hữu ngạn\", \"phe hữu\". Mẹo phân biệt: 右 có bộ 口 (miệng) — miệng ăn bằng tay phải.","ex":"洗手间在右边。","exPy":"Xǐshǒujiān zài yòubiān.","exVi":"Nhà vệ sinh ở bên phải.","w":"洗手间 在 右边。"},{"zh":"旁边","py":"pángbiān","vi":"bên cạnh","hv":"bàng biên","note":"Tiếng Việt: \"bàng quan\" (đứng bên ngoài nhìn vào).","ex":"宾馆旁边有一家饭馆。","exPy":"Bīnguǎn pángbiān yǒu yì jiā fànguǎn.","exVi":"Cạnh khách sạn có một quán ăn.","w":"宾馆 旁边 有 一 家 饭馆。"},{"zh":"外","py":"wài","vi":"bên ngoài","hv":"ngoại","note":"Tiếng Việt: \"ngoại ô\", \"hải ngoại\", \"ngoại ngữ\". Trái nghĩa với 里 (trong).","ex":"外面很冷，请关门。","exPy":"Wàimiàn hěn lěng, qǐng guān mén.","exVi":"Bên ngoài lạnh lắm, xin đóng cửa.","w":"外面 很 冷， 请 关 门。"},{"zh":"房间","py":"fángjiān","vi":"căn phòng","hv":"phòng gian","note":"房 chính là \"phòng\" tiếng Việt. 间 = \"gian\" trong \"gian nhà\", \"không gian\".","ex":"我的房间在三楼。","exPy":"Wǒ de fángjiān zài sān lóu.","exVi":"Phòng tôi ở tầng ba.","w":"我 的 房间 在 三 楼。"},{"zh":"宾馆","py":"bīnguǎn","vi":"khách sạn","hv":"tân quán","note":"宾 = \"tân\" trong \"tân khách\" (khách). 馆 = \"quán\". Nghĩa đen: quán cho khách. Còn gọi là 酒店.","ex":"我住在这个宾馆。","exPy":"Wǒ zhù zài zhège bīnguǎn.","exVi":"Tôi ở khách sạn này.","w":"我 住 在 这个 宾馆。"},{"zh":"进","py":"jìn","vi":"vào, đi vào","hv":"tiến","note":"Bộ 辶 (đi đường). Tiếng Việt: \"tiến vào\", \"tiến bộ\". Mời vào: 请进！","ex":"请进，请坐。","exPy":"Qǐng jìn, qǐng zuò.","exVi":"Mời vào, mời ngồi.","w":"请 进， 请 坐。"},{"zh":"出","py":"chū","vi":"ra, đi ra","hv":"xuất","note":"Hình hai ngọn núi chồng lên — mọc ra. Tiếng Việt: \"xuất phát\", \"xuất khẩu\", \"xuất hiện\".","ex":"他刚才出去了。","exPy":"Tā gāngcái chūqu le.","exVi":"Anh ấy vừa ra ngoài.","w":"他 刚才 出去 了。"},{"zh":"过","py":"guò","vi":"qua; đã từng","hv":"quá","note":"Tiếng Việt: \"quá khứ\", \"vượt quá\". Là chữ ngữ pháp quan trọng nhất bài này.","ex":"你去过北京吗？","exPy":"Nǐ qù guo Běijīng ma?","exVi":"Bạn từng đi Bắc Kinh chưa?","w":"你 去 过 北京 吗？"},{"zh":"门","py":"mén","vi":"cửa","hv":"môn","note":"Bộ thủ đã học — hình hai cánh cửa. Tiếng Việt: \"môn\" trong \"gia môn\", \"chuyên môn\".","ex":"请关门。","exPy":"Qǐng guān mén.","exVi":"Xin đóng cửa.","w":"请 关 门。"}],"newChars":["左","边","右","旁","房","宾","进"],"outro":"很好！Xong bài 33."};
G.ROOMS["zh-l034"] = {"id":"zh-l034","lang":"zh","level":2,"no":34,"teacher":"wang","title":"HSK2 · Bài 34 · 你喜欢什么运动？ Thể thao và giải trí","intro":["你喜欢什么运动？","Bài 34: Nói về sở thích vận động, hiểu \"động từ ly hợp\" và biết khi nào dùng 打, khi nào dùng 踢. Bấm 1 · Học để bắt đầu."],"introPy":"Nǐ xǐhuan shénme yùndòng?","gram":{"t":"Động từ ly hợp — một từ nhưng tách ra được","b":"唱歌 · 跳舞 · 跑步 · 游泳 · 睡觉 · 上班","d":"Đây là hiện tượng lạ với người Việt: các từ này thật ra là ĐỘNG TỪ + TÂN NGỮ dính lại. Muốn thêm gì thì phải chèn vào GIỮA, không thêm vào sau. Nói 我唱歌了两个小时 là sai, phải là 我唱了两个小时歌.","ex":[["我跑了三十分钟步。","Tôi chạy bộ ba mươi phút.","Wǒ pǎo le sānshí fēnzhōng bù."],["他唱了一个歌。","Anh ấy hát một bài.","Tā chàng le yí ge gē."],["我睡了八个小时觉。","Tôi ngủ tám tiếng.","Wǒ shuì le bā ge xiǎoshí jiào."]]},"grams":[{"t":"Động từ ly hợp — một từ nhưng tách ra được","b":"唱歌 · 跳舞 · 跑步 · 游泳 · 睡觉 · 上班","d":"Đây là hiện tượng lạ với người Việt: các từ này thật ra là ĐỘNG TỪ + TÂN NGỮ dính lại. Muốn thêm gì thì phải chèn vào GIỮA, không thêm vào sau. Nói 我唱歌了两个小时 là sai, phải là 我唱了两个小时歌.","ex":[["我跑了三十分钟步。","Tôi chạy bộ ba mươi phút.","Wǒ pǎo le sānshí fēnzhōng bù."],["他唱了一个歌。","Anh ấy hát một bài.","Tā chàng le yí ge gē."],["我睡了八个小时觉。","Tôi ngủ tám tiếng.","Wǒ shuì le bā ge xiǎoshí jiào."]]},{"t":"打 hay 踢 — đánh bóng hay đá bóng?","b":"打 dùng TAY · 踢 dùng CHÂN","d":"Rất logic: 打篮球 (bóng rổ, dùng tay), 打网球 (tennis), nhưng 踢足球 (bóng đá, dùng chân). Chữ 踢 có bộ ⻊ (chân) nên nhìn là đoán ra.","ex":[["他会打篮球。","Cậu ấy biết chơi bóng rổ.","Tā huì dǎ lánqiú."],["我不会踢足球。","Tôi không biết đá bóng.","Wǒ bú huì tī zúqiú."]]},{"t":"Bổ ngữ trình độ với 得 — làm việc gì đó GIỎI đến đâu","b":"Động từ + 得 + tính từ","d":"Muốn khen ai làm việc gì giỏi thì dùng 得. Với động từ ly hợp phải LẶP LẠI động từ: 她跳舞跳得很好, chứ không nói 她跳舞得很好.","ex":[["他跑得很快。","Anh ấy chạy rất nhanh.","Tā pǎo de hěn kuài."],["她唱歌唱得很好。","Cô ấy hát rất hay.","Tā chànggē chàng de hěn hǎo."],["你说汉语说得很好。","Bạn nói tiếng Trung rất giỏi.","Nǐ shuō Hànyǔ shuō de hěn hǎo."]]}],"items":[{"zh":"运动","py":"yùndòng","vi":"vận động, thể thao","hv":"vận động","note":"Chính là \"vận động\" tiếng Việt. Vừa là danh từ (môn thể thao) vừa là động từ (tập luyện).","ex":"你喜欢什么运动？","exPy":"Nǐ xǐhuan shénme yùndòng?","exVi":"Bạn thích môn thể thao nào?","w":"你 喜欢 什么 运动？"},{"zh":"跑步","py":"pǎobù","vi":"chạy bộ","hv":"bào bộ","note":"跑 (chạy, bộ ⻊ chân) + 步 (bước). Là động từ ly hợp: tách ra được thành 跑了三十分钟步.","ex":"我每天早上去跑步。","exPy":"Wǒ měi tiān zǎoshang qù pǎobù.","exVi":"Sáng nào tôi cũng đi chạy bộ.","w":"我 每 天 早上 去 跑步。"},{"zh":"游泳","py":"yóuyǒng","vi":"bơi lội","hv":"du vịnh","note":"Cả hai chữ đều có bộ 氵 (nước) — nhìn là biết liên quan tới nước.","ex":"我最喜欢游泳。","exPy":"Wǒ zuì xǐhuan yóuyǒng.","exVi":"Tôi thích bơi nhất.","w":"我 最 喜欢 游泳。"},{"zh":"打篮球","py":"dǎ lánqiú","vi":"chơi bóng rổ","hv":"đả lam cầu","note":"打 (đánh) + 篮 (cái rổ, bộ 竹 tre) + 球 (quả bóng, bộ 王 tức ngọc). Nghĩa đen: đánh bóng vào rổ.","ex":"他喜欢打篮球。","exPy":"Tā xǐhuan dǎ lánqiú.","exVi":"Cậu ấy thích chơi bóng rổ.","w":"他 喜欢 打篮球。"},{"zh":"踢足球","py":"tī zúqiú","vi":"đá bóng","hv":"thích túc cầu","note":"足球 chính là \"túc cầu\" — tên gọi cũ của bóng đá trong tiếng Việt. 踢 = đá, có bộ ⻊ (chân).","ex":"我们下午去踢足球吧。","exPy":"Wǒmen xiàwǔ qù tī zúqiú ba.","exVi":"Chiều nay đi đá bóng đi.","w":"我们 下午 去 踢足球 吧。"},{"zh":"跳舞","py":"tiàowǔ","vi":"nhảy múa, khiêu vũ","hv":"khiêu vũ","note":"Chính là \"khiêu vũ\" tiếng Việt. 跳 (nhảy, bộ ⻊) + 舞 (múa).","ex":"她跳舞跳得很漂亮。","exPy":"Tā tiàowǔ tiào de hěn piàoliang.","exVi":"Cô ấy nhảy rất đẹp.","w":"她 跳舞 跳 得 很 漂亮。"},{"zh":"唱歌","py":"chànggē","vi":"hát","hv":"xướng ca","note":"Chính là \"xướng ca\" tiếng Việt. Cả hai chữ đều có bộ 口 hoặc 欠 (há miệng).","ex":"晚上我们一起唱歌吧。","exPy":"Wǎnshang wǒmen yìqǐ chànggē ba.","exVi":"Tối nay cùng đi hát đi.","w":"晚上 我们 一起 唱歌 吧。"},{"zh":"玩","py":"wán","vi":"chơi","hv":"ngoạn","note":"Bộ 王 (ngọc) — vốn nghĩa là mân mê viên ngọc. Tiếng Việt: \"du ngoạn\", \"ngoạn mục\".","ex":"孩子们在外面玩得很高兴。","exPy":"Háizimen zài wàimiàn wán de hěn gāoxìng.","exVi":"Bọn trẻ chơi ngoài kia vui lắm.","w":"孩子 们 在 外面 玩 得 很 高兴。"},{"zh":"笑","py":"xiào","vi":"cười","hv":"tiếu","note":"Bộ 竹 (tre) ở trên — như hai mắt nheo lại. Tiếng Việt: \"tiếu lâm\", \"nụ cười\".","ex":"他说的话让大家都笑了。","exPy":"Tā shuō de huà ràng dàjiā dōu xiào le.","exVi":"Câu anh ấy nói làm mọi người đều cười.","w":"他 说 的话 让 大家 都 笑 了。"},{"zh":"一起","py":"yìqǐ","vi":"cùng nhau","hv":"nhất khởi","note":"Đứng TRƯỚC động từ: 一起去 (cùng đi). Không đặt cuối câu như tiếng Việt.","ex":"我们一起去吧。","exPy":"Wǒmen yìqǐ qù ba.","exVi":"Chúng ta cùng đi đi.","w":"我们 一起 去 吧。"}],"newChars":["运","跑","步","游","泳","篮","踢","足","跳","舞","唱","歌"],"outro":"很好！Xong bài 34."};
G.ROOMS["zh-l035"] = {"id":"zh-l035","lang":"zh","level":2,"no":35,"teacher":"wang","title":"HSK2 · Bài 35 · 旅游计划 Kế hoạch du lịch","intro":["我想去中国旅游。","Bài 35: Bàn kế hoạch, xin phép bằng 可以, rủ rê bằng 吧 và ngăn cản bằng 别. Bấm 1 · Học để bắt đầu."],"introPy":"Wǒ xiǎng qù Zhōngguó lǚyóu.","gram":{"t":"会 / 能 / 可以 — ba chữ \"có thể\" khác nhau","b":"会 = biết làm (kỹ năng) · 能 = làm được (điều kiện) · 可以 = được phép","d":"Người Việt hay dùng lẫn vì tiếng Việt chỉ có một chữ \"có thể\". Ba câu này khác hẳn nhau: 我会开车 (tôi biết lái xe), 我今天不能开车 (hôm nay tôi không lái được, vì mệt), 这里可以停车吗 (ở đây được đỗ xe không).","ex":[["我会说汉语。","Tôi biết nói tiếng Trung. (kỹ năng)","Wǒ huì shuō Hànyǔ."],["我明天不能来。","Mai tôi không đến được. (điều kiện)","Wǒ míngtiān bù néng lái."],["我可以问一个问题吗？","Tôi hỏi một câu được không? (xin phép)","Wǒ kěyǐ wèn yí ge wèntí ma?"]]},"grams":[{"t":"会 / 能 / 可以 — ba chữ \"có thể\" khác nhau","b":"会 = biết làm (kỹ năng) · 能 = làm được (điều kiện) · 可以 = được phép","d":"Người Việt hay dùng lẫn vì tiếng Việt chỉ có một chữ \"có thể\". Ba câu này khác hẳn nhau: 我会开车 (tôi biết lái xe), 我今天不能开车 (hôm nay tôi không lái được, vì mệt), 这里可以停车吗 (ở đây được đỗ xe không).","ex":[["我会说汉语。","Tôi biết nói tiếng Trung. (kỹ năng)","Wǒ huì shuō Hànyǔ."],["我明天不能来。","Mai tôi không đến được. (điều kiện)","Wǒ míngtiān bù néng lái."],["我可以问一个问题吗？","Tôi hỏi một câu được không? (xin phép)","Wǒ kěyǐ wèn yí ge wèntí ma?"]]},{"t":"吧 — rủ rê và đề nghị","b":"Câu + 吧","d":"Thêm 吧 làm câu mềm hẳn đi. 我们走 nghe như ra lệnh, còn 我们走吧 là \"chúng ta đi thôi\". Cũng dùng để đoán: 你是中国人吧？(bạn là người Trung Quốc phải không?).","ex":[["我们一起去吧。","Chúng ta cùng đi đi.","Wǒmen yìqǐ qù ba."],["你休息一下吧。","Bạn nghỉ chút đi.","Nǐ xiūxi yíxià ba."],["你是老师吧？","Bạn là giáo viên phải không?","Nǐ shì lǎoshī ba?"]]},{"t":"别 — cấm đoán nhẹ nhàng","b":"别 + động từ (+ 了)","d":"别 nghĩa là \"đừng\". Thêm 了 ở cuối nghĩa là \"thôi đừng làm nữa\" (việc đang diễn ra). So sánh: 别说 (đừng nói) và 别说了 (thôi đừng nói nữa).","ex":[["别忘了带票。","Đừng quên mang vé.","Bié wàng le dài piào."],["别走这么快。","Đừng đi nhanh thế.","Bié zǒu zhème kuài."],["别说了！","Thôi đừng nói nữa!","Bié shuō le!"]]}],"items":[{"zh":"旅游","py":"lǚyóu","vi":"du lịch","hv":"lữ du","note":"Tiếng Việt: \"lữ hành\", \"lữ khách\", \"du lịch\" — cùng gốc chữ Hán này.","ex":"我想去中国旅游。","exPy":"Wǒ xiǎng qù Zhōngguó lǚyóu.","exVi":"Tôi muốn đi du lịch Trung Quốc.","w":"我 想 去 中国 旅游。"},{"zh":"希望","py":"xīwàng","vi":"hy vọng, mong","hv":"hy vọng","note":"Chính là \"hy vọng\" tiếng Việt. Sau 希望 là CẢ MỘT CÂU, giống 觉得.","ex":"我希望明年去北京。","exPy":"Wǒ xīwàng míngnián qù Běijīng.","exVi":"Tôi mong sang năm được đi Bắc Kinh.","w":"我 希望 明年 去 北京。"},{"zh":"可能","py":"kěnéng","vi":"có thể, có lẽ","hv":"khả năng","note":"Chính là \"khả năng\" tiếng Việt. Diễn đạt sự phỏng đoán, không chắc chắn.","ex":"他可能不来了。","exPy":"Tā kěnéng bù lái le.","exVi":"Có lẽ anh ấy không đến nữa.","w":"他 可能 不 来 了。"},{"zh":"可以","py":"kěyǐ","vi":"được phép, có thể","hv":"khả dĩ","note":"Tiếng Việt: \"khả dĩ\". Dùng để XIN PHÉP và CHO PHÉP — khác 能 (đủ điều kiện) và 会 (biết làm).","ex":"我可以问一个问题吗？","exPy":"Wǒ kěyǐ wèn yí ge wèntí ma?","exVi":"Tôi hỏi một câu được không?","w":"我 可以 问 一 个 问题 吗？"},{"zh":"开始","py":"kāishǐ","vi":"bắt đầu","hv":"khai thuỷ","note":"开 (mở) + 始 (đầu tiên, bộ 女). Tiếng Việt: \"khai giảng\", \"khai mạc\", \"nguyên thuỷ\".","ex":"我们什么时候开始？","exPy":"Wǒmen shénme shíhou kāishǐ?","exVi":"Khi nào chúng ta bắt đầu?","w":"我们 什么 时候 开始？"},{"zh":"送","py":"sòng","vi":"tặng; tiễn, đưa đi","hv":"tống","note":"Bộ 辶 (đi đường). Tiếng Việt: \"tống tiễn\", \"hộ tống\". Hai nghĩa: tặng quà và tiễn người.","ex":"我送你去机场吧。","exPy":"Wǒ sòng nǐ qù jīchǎng ba.","exVi":"Để tôi tiễn bạn ra sân bay nhé.","w":"我 送 你 去 机场 吧。"},{"zh":"找","py":"zhǎo","vi":"tìm; tìm gặp","hv":"trảo","note":"Bộ 扌 (tay) — tìm bằng tay. Còn nghĩa \"tìm ai đó\": 我找王老师.","ex":"我在找我的手机。","exPy":"Wǒ zài zhǎo wǒ de shǒujī.","exVi":"Tôi đang tìm điện thoại.","w":"我 在 找 我 的 手机。"},{"zh":"等","py":"děng","vi":"đợi, chờ","hv":"đẳng","note":"Bộ 竹 (tre) ở trên. Còn nghĩa \"hạng, đẳng cấp\" như trong tiếng Việt.","ex":"请等一下，我马上来。","exPy":"Qǐng děng yíxià, wǒ mǎshàng lái.","exVi":"Xin đợi chút, tôi tới ngay.","w":"请 等 一下， 我 马上 来。"},{"zh":"别","py":"bié","vi":"đừng; khác","hv":"biệt","note":"Bộ 刂 (dao) — cắt ra thành cái khác. Tiếng Việt: \"biệt ly\", \"đặc biệt\", \"phân biệt\".","ex":"别忘了带护照。","exPy":"Bié wàng le dài hùzhào.","exVi":"Đừng quên mang hộ chiếu.","w":"别 忘 了 带 护照。"},{"zh":"吧","py":"ba","vi":"(trợ từ: rủ rê, đề nghị)","hv":"ba","note":"Bộ 口 (miệng). Đặt cuối câu để rủ rê hoặc đề nghị nhẹ nhàng — giống \"…đi\", \"…nhé\" tiếng Việt.","ex":"我们走吧。","exPy":"Wǒmen zǒu ba.","exVi":"Chúng ta đi thôi.","w":"我们 走 吧。"}],"newChars":["旅","希","望","以","始","送","找","等","吧"],"outro":"很好！Xong bài 35."};
G.ROOMS["zh-l036"] = {"id":"zh-l036","lang":"zh","level":2,"no":36,"teacher":"wang","title":"HSK2 · Bài 36 · 他比我高 So sánh và chúc mừng","intro":["他比我高一点儿。","Bài 36: Dùng 比 để so sánh — điểm ngữ pháp lớn nhất của HSK 2 — và nói lời chúc. Bấm 1 · Học để bắt đầu."],"introPy":"Tā bǐ wǒ gāo yìdiǎnr.","gram":{"t":"比 — cấu trúc so sánh hơn","b":"A + 比 + B + tính từ","d":"Điểm ngữ pháp lớn nhất HSK 2. Quan trọng: KHÔNG được dùng 很 trong câu có 比. Nói 他比我很高 là SAI, phải là 他比我高.","ex":[["他比我高。","Anh ấy cao hơn tôi.","Tā bǐ wǒ gāo."],["今天比昨天冷。","Hôm nay lạnh hơn hôm qua.","Jīntiān bǐ zuótiān lěng."],["这个比那个便宜。","Cái này rẻ hơn cái kia.","Zhège bǐ nàge piányi."]]},"grams":[{"t":"比 — cấu trúc so sánh hơn","b":"A + 比 + B + tính từ","d":"Điểm ngữ pháp lớn nhất HSK 2. Quan trọng: KHÔNG được dùng 很 trong câu có 比. Nói 他比我很高 là SAI, phải là 他比我高.","ex":[["他比我高。","Anh ấy cao hơn tôi.","Tā bǐ wǒ gāo."],["今天比昨天冷。","Hôm nay lạnh hơn hôm qua.","Jīntiān bǐ zuótiān lěng."],["这个比那个便宜。","Cái này rẻ hơn cái kia.","Zhège bǐ nàge piányi."]]},{"t":"Nói hơn BAO NHIÊU","b":"A + 比 + B + tính từ + mức chênh","d":"Phần chênh lệch đặt ở CUỐI câu, sau tính từ. Ngược với tiếng Việt hay nói \"cao hơn tôi 5 phân\" — trật tự thật ra giống nhau, chỉ cần nhớ đừng chèn vào giữa.","ex":[["他比我大两岁。","Anh ấy hơn tôi hai tuổi.","Tā bǐ wǒ dà liǎng suì."],["这个比那个贵十块。","Cái này đắt hơn cái kia mười đồng.","Zhège bǐ nàge guì shí kuài."],["他比我高一点儿。","Anh ấy cao hơn tôi một chút.","Tā bǐ wǒ gāo yìdiǎnr."]]},{"t":"Phủ định của so sánh: 没有 chứ không phải 不比","b":"A + 没有 + B + tính từ","d":"Muốn nói \"tôi không cao bằng anh ấy\" thì dùng 我没有他高, chứ không dùng 我不比他高 (câu này nghĩa hơi khác: \"tôi chẳng cao hơn anh ấy đâu\", mang ý phản bác).","ex":[["我没有他高。","Tôi không cao bằng anh ấy.","Wǒ méiyǒu tā gāo."],["今天没有昨天冷。","Hôm nay không lạnh bằng hôm qua.","Jīntiān méiyǒu zuótiān lěng."]]},{"t":"姓 và 叫 — hỏi họ hay hỏi tên?","b":"您贵姓？ → 我姓… · 你叫什么名字？ → 我叫…","d":"您贵姓 là câu hỏi họ lịch sự nhất. Trả lời chỉ nói HỌ: 我姓王. Tuyệt đối không trả lời 我贵姓王 — chữ 贵 là để tôn người khác, không dùng cho mình.","ex":[["您贵姓？","Xin hỏi quý danh?","Nín guìxìng?"],["我姓王，叫王小明。","Tôi họ Vương, tên Vương Tiểu Minh.","Wǒ xìng Wáng, jiào Wáng Xiǎomíng."]]}],"items":[{"zh":"比","py":"bǐ","vi":"hơn, so với","hv":"tỷ","note":"Hình hai người đứng cạnh nhau để so. Tiếng Việt: \"tỷ lệ\", \"so sánh\", \"đối tỷ\".","ex":"他比我高一点儿。","exPy":"Tā bǐ wǒ gāo yìdiǎnr.","exVi":"Anh ấy cao hơn tôi một chút.","w":"他 比 我 高 一点儿。"},{"zh":"真","py":"zhēn","vi":"thật, thật là","hv":"chân","note":"Tiếng Việt: \"chân thật\", \"chân lý\", \"chân thành\". Dùng để cảm thán: 真好！","ex":"这条路真长。","exPy":"Zhè tiáo lù zhēn cháng.","exVi":"Con đường này dài thật.","w":"这 条 路 真 长。"},{"zh":"高","py":"gāo","vi":"cao","hv":"cao","note":"Chính là chữ \"cao\" tiếng Việt. Hình cái tháp nhiều tầng. Cũng có trong 高兴 (bài 2).","ex":"他很高。","exPy":"Tā hěn gāo.","exVi":"Anh ấy rất cao.","w":"他 很 高。"},{"zh":"长","py":"cháng","vi":"dài","hv":"trường","note":"Đọc cháng = dài (\"trường kỳ\"); đọc zhǎng = lớn lên, trưởng (\"trưởng thành\", \"hiệu trưởng\"). Một chữ hai âm hai nghĩa.","ex":"这条路很长。","exPy":"Zhè tiáo lù hěn cháng.","exVi":"Con đường này rất dài.","w":"这 条 路 很 长。"},{"zh":"您","py":"nín","vi":"ngài, ông/bà (kính ngữ)","hv":"nâm","note":"你 có thêm 心 (trái tim) ở dưới — xưng hô có để tâm, tức là kính trọng. Dùng với người lớn tuổi, khách hàng, cấp trên.","ex":"您好，您贵姓？","exPy":"Nín hǎo, nín guìxìng?","exVi":"Chào ngài, xin hỏi quý danh?","w":"您 好， 您 贵姓？"},{"zh":"它","py":"tā","vi":"nó (đồ vật, con vật)","hv":"tha","note":"Bộ 宀 (mái nhà). Đọc giống hệt 他 và 她 nhưng dùng cho VẬT, không dùng cho người.","ex":"它是我家的狗，它很可爱。","exPy":"Tā shì wǒ jiā de gǒu, tā hěn kě'ài.","exVi":"Nó là con chó nhà tôi, nó rất đáng yêu.","w":"它 是 我 家 的 狗， 它 很 可爱。"},{"zh":"也","py":"yě","vi":"cũng","hv":"dã","note":"Luôn đứng SAU chủ ngữ, TRƯỚC động từ — giống hệt quy tắc của 都. Không đặt đầu câu.","ex":"我姓陈，我也是学生。","exPy":"Wǒ xìng Chén, wǒ yě shì xuésheng.","exVi":"Tôi họ Trần, tôi cũng là học sinh.","w":"我 姓 陈， 我 也 是 学生。"},{"zh":"姓","py":"xìng","vi":"họ; mang họ","hv":"tính","note":"女 (nữ) + 生 (sinh) — họ truyền theo dòng mẹ thời cổ. Tiếng Việt: \"tính danh\", \"bách tính\".","ex":"我姓王。","exPy":"Wǒ xìng Wáng.","exVi":"Tôi họ Vương.","w":"我 姓 王。"},{"zh":"生日","py":"shēngrì","vi":"sinh nhật","hv":"sinh nhật","note":"Chính là \"sinh nhật\" tiếng Việt: 生 (sinh) + 日 (nhật, ngày).","ex":"今天是我的生日。","exPy":"Jīntiān shì wǒ de shēngrì.","exVi":"Hôm nay là sinh nhật tôi.","w":"今天 是 我 的 生日。"},{"zh":"快乐","py":"kuàilè","vi":"vui vẻ, hạnh phúc","hv":"khoái lạc","note":"Tiếng Việt \"khoái lạc\" nghiêng về hưởng thụ, còn 快乐 tiếng Trung chỉ đơn giản là VUI. Dùng trong mọi lời chúc.","ex":"生日快乐！","exPy":"Shēngrì kuàilè!","exVi":"Chúc mừng sinh nhật!","w":"生日 快乐！"}],"newChars":["真","长","您","它","姓","日","乐"],"outro":"很好！Xong bài 36."};
G.ROOMS["zh-l037"] = {"id":"zh-l037","lang":"zh","level":2,"no":37,"teacher":"wang","title":"HSK2 · Bài 37 · 因为……所以…… Nối câu dài","intro":["你为什么不来？","Bài 37: Ghép câu dài bằng cặp liên từ, và nói việc ĐANG diễn ra bằng 正在 và 着. Bấm 1 · Học để bắt đầu."],"introPy":"Nǐ wèi shénme bù lái?","gram":{"t":"因为 … 所以 … — dùng CẢ HAI vế","b":"因为 + nguyên nhân, 所以 + kết quả","d":"Khác tiếng Việt và tiếng Anh: tiếng Trung dùng ĐỦ CẢ CẶP, không bỏ vế nào. Tiếng Việt nói \"Vì mưa nên tôi không đi\" — cũng có cặp \"vì… nên…\", nên người Việt quen ngay.","ex":[["因为下雨，所以我没去。","Vì trời mưa nên tôi không đi.","Yīnwèi xiàyǔ, suǒyǐ wǒ méi qù."],["因为很累，所以他没来。","Vì mệt nên anh ấy không đến.","Yīnwèi hěn lèi, suǒyǐ tā méi lái."]]},"grams":[{"t":"因为 … 所以 … — dùng CẢ HAI vế","b":"因为 + nguyên nhân, 所以 + kết quả","d":"Khác tiếng Việt và tiếng Anh: tiếng Trung dùng ĐỦ CẢ CẶP, không bỏ vế nào. Tiếng Việt nói \"Vì mưa nên tôi không đi\" — cũng có cặp \"vì… nên…\", nên người Việt quen ngay.","ex":[["因为下雨，所以我没去。","Vì trời mưa nên tôi không đi.","Yīnwèi xiàyǔ, suǒyǐ wǒ méi qù."],["因为很累，所以他没来。","Vì mệt nên anh ấy không đến.","Yīnwèi hěn lèi, suǒyǐ tā méi lái."]]},{"t":"虽然 … 但是 … — tuy… nhưng…","b":"虽然 + sự thật, 但是 + điều trái ngược","d":"Cũng dùng đủ cặp. Chú ý 虽然 có thể đứng trước hoặc sau chủ ngữ đều được: 虽然他很忙 hoặc 他虽然很忙.","ex":[["虽然很贵，但是我很喜欢。","Tuy đắt nhưng tôi rất thích.","Suīrán hěn guì, dànshì wǒ hěn xǐhuan."],["虽然他很忙，但是每天都运动。","Tuy bận nhưng ngày nào anh ấy cũng tập thể dục.","Suīrán tā hěn máng, dànshì měi tiān dōu yùndòng."]]},{"t":"正在 và 着 — đang làm khác đang ở trạng thái","b":"正在 + động từ (hành động) · động từ + 着 (trạng thái)","d":"正在开门 = đang mở cửa (hành động diễn ra). 门开着 = cửa đang mở (trạng thái sau khi mở xong). Đây là chỗ người Việt hay lẫn vì tiếng Việt dùng chung chữ \"đang\".","ex":[["我正在写作业。","Tôi đang làm bài tập. (hành động)","Wǒ zhèngzài xiě zuòyè."],["他穿着一件红衣服。","Anh ấy đang mặc áo đỏ. (trạng thái)","Tā chuān zhe yí jiàn hóng yīfu."],["窗户开着呢。","Cửa sổ đang mở đấy.","Chuānghu kāi zhe ne."]]},{"t":"第 + số = số thứ tự","b":"第一 · 第二 · 第三 · 第一次","d":"Chỉ cần thêm 第 vào trước con số. Giống hệt \"đệ nhất, đệ nhị\" trong tiếng Việt Hán Việt. Nhớ có lượng từ ở sau: 第一个人, 第二本书.","ex":[["这是第一次。","Đây là lần đầu tiên.","Zhè shì dì-yī cì."],["他是第三个来的。","Anh ấy là người thứ ba đến.","Tā shì dì-sān ge lái de."]]}],"items":[{"zh":"因为","py":"yīnwèi","vi":"bởi vì","hv":"nhân vi","note":"因 = \"nhân\" trong \"nguyên nhân\", \"nhân quả\". Gần như luôn đi cặp với 所以.","ex":"因为我生病了，所以没来。","exPy":"Yīnwèi wǒ shēngbìng le, suǒyǐ méi lái.","exVi":"Vì tôi bị ốm nên không đến.","w":"因为 我 生病 了， 所以 没 来。"},{"zh":"所以","py":"suǒyǐ","vi":"cho nên, vì vậy","hv":"sở dĩ","note":"Chính là \"sở dĩ\" tiếng Việt (\"sở dĩ như vậy là vì…\"). Đứng đầu vế KẾT QUẢ.","ex":"我很累，所以想休息。","exPy":"Wǒ hěn lèi, suǒyǐ xiǎng xiūxi.","exVi":"Tôi rất mệt nên muốn nghỉ.","w":"我 很 累， 所以 想 休息。"},{"zh":"虽然","py":"suīrán","vi":"tuy, mặc dù","hv":"tuy nhiên","note":"Đúng là \"tuy nhiên\" tiếng Việt, nhưng vị trí khác: 虽然 đứng ở vế ĐẦU (vế nhượng bộ), không đứng ở vế sau.","ex":"虽然汉语很难，但是很有意思。","exPy":"Suīrán Hànyǔ hěn nán, dànshì hěn yǒu yìsi.","exVi":"Tuy tiếng Trung khó nhưng rất thú vị.","w":"虽然 汉语 很 难， 但是 很 有意思。"},{"zh":"但是","py":"dànshì","vi":"nhưng, tuy nhiên","hv":"đãn thị","note":"Đứng đầu vế TƯƠNG PHẢN. Nói tắt là 但. Đi cặp với 虽然.","ex":"汉语很难，但是很有意思。","exPy":"Hànyǔ hěn nán, dànshì hěn yǒu yìsi.","exVi":"Tiếng Trung khó nhưng thú vị.","w":"汉语 很 难， 但是 很 有意思。"},{"zh":"为什么","py":"wèi shénme","vi":"tại sao","hv":"vi thập ma","note":"为 (vì) + 什么 (cái gì) = \"vì cái gì\". Trả lời bằng 因为…","ex":"你为什么不来？","exPy":"Nǐ wèi shénme bù lái?","exVi":"Sao bạn không đến?","w":"你 为什么 不 来？"},{"zh":"得","py":"de","vi":"(trợ từ nối bổ ngữ trình độ)","hv":"đắc","note":"Đọc nhẹ là de khi làm trợ từ; đọc dé nghĩa là \"được, đạt\" (\"đắc lợi\"); đọc děi nghĩa là \"phải\".","ex":"他汉语说得比我好。","exPy":"Tā Hànyǔ shuō de bǐ wǒ hǎo.","exVi":"Anh ấy nói tiếng Trung giỏi hơn tôi.","w":"他 汉语 说 得 比 我 好。"},{"zh":"着","py":"zhe","vi":"(trợ từ: đang ở trạng thái)","hv":"trước","note":"Diễn tả TRẠNG THÁI kéo dài, khác 正在 (hành động đang diễn ra). 门开着 = cửa đang mở (trạng thái).","ex":"门开着，请进。","exPy":"Mén kāi zhe, qǐng jìn.","exVi":"Cửa đang mở, mời vào.","w":"门 开 着， 请 进。"},{"zh":"正在","py":"zhèngzài","vi":"đang (làm gì)","hv":"chính tại","note":"Đứng TRƯỚC động từ. Có thể rút gọn thành 正 hoặc 在, hoặc thêm 呢 ở cuối câu.","ex":"我正在准备考试。","exPy":"Wǒ zhèngzài zhǔnbèi kǎoshì.","exVi":"Tôi đang chuẩn bị thi.","w":"我 正在 准备 考试。"},{"zh":"第一","py":"dì-yī","vi":"thứ nhất","hv":"đệ nhất","note":"Chính là \"đệ nhất\" tiếng Việt. Thêm 第 vào trước số là thành số thứ tự: 第二, 第三…","ex":"这是我第一次来中国。","exPy":"Zhè shì wǒ dì-yī cì lái Zhōngguó.","exVi":"Đây là lần đầu tôi đến Trung Quốc.","w":"这 是 我 第一 次 来 中国。"},{"zh":"服务员","py":"fúwùyuán","vi":"nhân viên phục vụ","hv":"phục vụ viên","note":"Chính là \"phục vụ viên\" tiếng Việt. 员 = \"viên\" trong \"nhân viên\", \"giáo viên\", \"đảng viên\".","ex":"服务员，请给我一杯水。","exPy":"Fúwùyuán, qǐng gěi wǒ yì bēi shuǐ.","exVi":"Bạn ơi, cho tôi một cốc nước.","w":"服务员， 请 给 我 一 杯 水。"}],"newChars":["虽","但","第","务","员"],"outro":"很好！Xong bài 37."};
G.ROOMS["zh-l039"] = {"id":"zh-l039","lang":"zh","level":2,"no":39,"teacher":"wang","title":"HSK2 · Bài 39 · 出来，进去 Ra, vào, về","intro":["你什么时候回来？","Bài 39: Dùng 来 và 去 sau động từ để chỉ hướng: lại gần người nói hay đi xa người nói. Bấm 1 · Học để bắt đầu."],"introPy":"Nǐ shénme shíhou huílai?","gram":{"t":"Động từ + 来 / 去: hướng so với người nói","b":"出来 / 出去 · 进来 / 进去 · 回来 / 回去","d":"来 là hướng về phía người nói, 去 là hướng ra xa người nói. Cùng một hành động \"đi vào\", người trong phòng nói 进来, người ngoài phòng nói 进去.","ex":[["外边很冷，快进来吧。","Ngoài trời lạnh lắm, vào nhanh đi.","Wàibian hěn lěng, kuài jìnlai ba."],["他不在家，出去了。","Anh ấy không có nhà, ra ngoài rồi.","Tā bú zài jiā, chūqu le."]]},"grams":[{"t":"Động từ + 来 / 去: hướng so với người nói","b":"出来 / 出去 · 进来 / 进去 · 回来 / 回去","d":"来 là hướng về phía người nói, 去 là hướng ra xa người nói. Cùng một hành động \"đi vào\", người trong phòng nói 进来, người ngoài phòng nói 进去.","ex":[["外边很冷，快进来吧。","Ngoài trời lạnh lắm, vào nhanh đi.","Wàibian hěn lěng, kuài jìnlai ba."],["他不在家，出去了。","Anh ấy không có nhà, ra ngoài rồi.","Tā bú zài jiā, chūqu le."]]},{"t":"Nơi chốn đứng giữa động từ và 来 / 去","b":"回家来 · 进教室去 · 回中国去","d":"Khi có nơi chốn, đặt nó vào giữa: 回家去, không nói 回去家.","ex":[["他回家去了。","Anh ấy về nhà rồi.","Tā huí jiā qù le."],["老师进教室来了。","Thầy giáo vào lớp rồi.","Lǎoshī jìn jiàoshì lái le."]]}],"items":[{"zh":"出来","py":"chūlái","vi":"đi ra (về phía người nói)","hv":"xuất lai","note":"出 (ra) + 来 (về phía mình). Người nói đang ở bên ngoài.","ex":"你快出来吧！","exPy":"Nǐ kuài chūlai ba!","exVi":"Bạn ra đây nhanh lên!","w":"你 快 出来 吧！"},{"zh":"出去","py":"chūqù","vi":"đi ra (xa người nói)","hv":"xuất khứ","note":"出 + 去 (đi xa mình). Người nói đang ở bên trong.","ex":"下雨了，我们不出去了。","exPy":"Xià yǔ le, wǒmen bù chūqu le.","exVi":"Trời mưa rồi, chúng ta không ra ngoài nữa.","w":"下雨 了， 我们 不 出去 了。"},{"zh":"进来","py":"jìnlái","vi":"đi vào (về phía người nói)","hv":"tiến lai","note":"进 = \"tiến\" trong \"tiến vào\". Mời khách vào nhà: 请进来.","ex":"请进来坐。","exPy":"Qǐng jìnlai zuò.","exVi":"Mời vào ngồi.","w":"请 进来 坐。"},{"zh":"进去","py":"jìnqù","vi":"đi vào (xa người nói)","hv":"tiến khứ","note":"Người nói đứng bên ngoài, người kia đi vào trong.","ex":"你先进去，我马上来。","exPy":"Nǐ xiān jìnqu, wǒ mǎshàng lái.","exVi":"Bạn vào trước đi, tôi đến ngay.","w":"你 先进 去， 我 马上 来。"},{"zh":"回来","py":"huílái","vi":"quay về (chỗ người nói)","hv":"hồi lai","note":"回 = \"hồi\" trong \"hồi hương\". Mẹ ở nhà hỏi con: 你几点回来？","ex":"你什么时候回来？","exPy":"Nǐ shénme shíhou huílai?","exVi":"Khi nào bạn về?","w":"你 什么 时候 回来？"},{"zh":"回去","py":"huíqù","vi":"quay về (nơi khác, xa người nói)","hv":"hồi khứ","note":"Đang ở chỗ bạn, nói mình về nhà: 我回去了.","ex":"太晚了，我回去了。","exPy":"Tài wǎn le, wǒ huíqu le.","exVi":"Muộn quá rồi, tôi về đây.","w":"太 晚 了， 我 回去 了。"},{"zh":"过来","py":"guòlái","vi":"lại đây","hv":"quá lai","note":"过 = đi qua. Gọi ai lại gần: 你过来一下.","ex":"小狗跑过来了。","exPy":"Xiǎo gǒu pǎo guòlai le.","exVi":"Con chó nhỏ chạy lại đây rồi.","w":"小 狗 跑 过来 了。"},{"zh":"出门","py":"chūmén","vi":"ra khỏi nhà, đi ra ngoài","hv":"xuất môn","note":"Nghĩa đen \"ra cửa\". Cũng có nghĩa đi xa: 出门在外 (đi xa nhà).","ex":"我早上八点出门。","exPy":"Wǒ zǎoshang bā diǎn chūmén.","exVi":"Tôi ra khỏi nhà lúc tám giờ sáng.","w":"我 早上 八 点 出门。"},{"zh":"出国","py":"chūguó","vi":"ra nước ngoài","hv":"xuất quốc","note":"出 + 国. Đi du học, công tác nước ngoài đều dùng.","ex":"她明年要出国学习。","exPy":"Tā míngnián yào chūguó xuéxí.","exVi":"Năm sau cô ấy sẽ ra nước ngoài học.","w":"她 明年 要 出国 学习。"},{"zh":"打开","py":"dǎkāi","vi":"mở ra; bật","hv":"đả khai","note":"Mở sách, mở cửa, bật máy tính đều dùng 打开. Ngược lại là 关上 / 关.","ex":"请大家打开电脑。","exPy":"Qǐng dàjiā dǎkāi diànnǎo.","exVi":"Mời mọi người bật máy tính.","w":"请 大家 打开 电脑。"}],"newChars":[],"outro":"很好！Xong bài 39."};
G.ROOMS["zh-l040"] = {"id":"zh-l040","lang":"zh","level":2,"no":40,"teacher":"wang","title":"HSK2 · Bài 40 · 上来，下去 Lên, xuống, trên, dưới","intro":["电梯坏了，我们走上去吧。","Bài 40: Dùng 上来 / 上去 / 下来 / 下去 / 起来 chỉ hướng lên xuống, và nói vị trí bằng 上面 / 下面 / 里面 / 外面. Bấm 1 · Học để bắt đầu."],"introPy":"Diàntī huài le, wǒmen zǒu shàngqu ba.","gram":{"t":"Động từ + 上 / 下 / 起 + 来 / 去","b":"走上去 · 跑下来 · 站起来","d":"Có thể ghép thêm động từ chỉ cách di chuyển ở trước: 走 (đi bộ), 跑 (chạy), 拿 (cầm). 起来 luôn đi với 来, không có 起去.","ex":[["他跑上楼去了。","Anh ấy chạy lên lầu rồi.","Tā pǎo shàng lóu qù le."],["请坐下来休息一下。","Mời ngồi xuống nghỉ một lát.","Qǐng zuò xiàlai xiūxi yíxià."]]},"grams":[{"t":"Động từ + 上 / 下 / 起 + 来 / 去","b":"走上去 · 跑下来 · 站起来","d":"Có thể ghép thêm động từ chỉ cách di chuyển ở trước: 走 (đi bộ), 跑 (chạy), 拿 (cầm). 起来 luôn đi với 来, không có 起去.","ex":[["他跑上楼去了。","Anh ấy chạy lên lầu rồi.","Tā pǎo shàng lóu qù le."],["请坐下来休息一下。","Mời ngồi xuống nghỉ một lát.","Qǐng zuò xiàlai xiūxi yíxià."]]},{"t":"Danh từ + 上面 / 下面 / 里面 / 外面","b":"桌子上面 · 椅子下面 · 房间里面","d":"Từ chỉ vị trí đứng sau danh từ. Hai chữ 面 / 边 dùng như nhau: 上面 = 上边.","ex":[["猫在椅子下面。","Con mèo ở dưới ghế.","Māo zài yǐzi xiàmian."],["房间里面很干净。","Bên trong phòng rất sạch.","Fángjiān lǐmian hěn gānjìng."]]}],"items":[{"zh":"上来","py":"shànglái","vi":"đi lên (về phía người nói)","hv":"thượng lai","note":"Người nói ở trên, người kia đi lên.","ex":"你上来看看吧。","exPy":"Nǐ shànglai kànkan ba.","exVi":"Bạn lên đây xem đi.","w":"你 上来 看 看 吧。"},{"zh":"上去","py":"shàngqù","vi":"đi lên (xa người nói)","hv":"thượng khứ","note":"Người nói ở dưới.","ex":"电梯坏了，我们走上去吧。","exPy":"Diàntī huài le, wǒmen zǒu shàngqu ba.","exVi":"Thang máy hỏng rồi, mình đi bộ lên nhé.","w":"电梯 坏 了， 我们 走 上去 吧。"},{"zh":"下来","py":"xiàlái","vi":"đi xuống (về phía người nói)","hv":"hạ lai","note":"Người nói ở dưới gọi người trên lầu: 快下来吃饭！","ex":"快下来吃饭！","exPy":"Kuài xiàlai chīfàn!","exVi":"Xuống ăn cơm nhanh lên!","w":"快 下来 吃 饭！"},{"zh":"下去","py":"xiàqù","vi":"đi xuống (xa người nói); tiếp tục","hv":"hạ khứ","note":"Ngoài nghĩa đi xuống, 下去 sau động từ còn nghĩa là \"tiếp tục\": 说下去 (nói tiếp đi).","ex":"你说下去，我在听。","exPy":"Nǐ shuō xiàqu, wǒ zài tīng.","exVi":"Bạn nói tiếp đi, tôi đang nghe.","w":"你 说 下去， 我 在 听。"},{"zh":"起来","py":"qǐlái","vi":"đứng dậy; bắt đầu","hv":"khởi lai","note":"起 = \"khởi\" trong \"khởi đầu\". 站起来 (đứng dậy), 笑起来 (bật cười).","ex":"听了他的话，大家都笑起来了。","exPy":"Tīng le tā de huà, dàjiā dōu xiào qǐlai le.","exVi":"Nghe anh ấy nói, mọi người đều bật cười.","w":"听 了 他 的话， 大家 都 笑 起来 了。"},{"zh":"上面","py":"shàngmiàn","vi":"phía trên, bên trên","hv":"thượng diện","note":"面 = mặt, phía. Hay đọc nhẹ: shàngmian.","ex":"你的手机在桌子上面。","exPy":"Nǐ de shǒujī zài zhuōzi shàngmian.","exVi":"Điện thoại của bạn ở trên bàn.","w":"你 的 手机 在 桌子 上面。"},{"zh":"下面","py":"xiàmiàn","vi":"phía dưới, bên dưới; tiếp theo","hv":"hạ diện","note":"Còn có nghĩa \"tiếp theo\": 下面请小王说.","ex":"下面请小王说一下。","exPy":"Xiàmian qǐng Xiǎo Wáng shuō yíxià.","exVi":"Tiếp theo mời Tiểu Vương nói đôi lời.","w":"下面 请 小 王 说 一下。"},{"zh":"里面","py":"lǐmiàn","vi":"bên trong","hv":"lý diện","note":"Giống 里边. Đối lập với 外面.","ex":"外面下雨了，我们在里面等吧。","exPy":"Wàimian xià yǔ le, wǒmen zài lǐmian děng ba.","exVi":"Ngoài trời mưa rồi, chúng ta đợi ở trong nhé.","w":"外面 下雨 了， 我们 在 里面 等 吧。"},{"zh":"外面","py":"wàimiàn","vi":"bên ngoài","hv":"ngoại diện","note":"Giống 外边.","ex":"外面有人找你。","exPy":"Wàimian yǒu rén zhǎo nǐ.","exVi":"Ngoài kia có người tìm bạn.","w":"外面 有 人 找 你。"},{"zh":"面","py":"miàn","vi":"mặt, phía (hậu tố phương hướng)","hv":"diện","note":"\"Diện\" trong \"phương diện\", \"mặt tiền\". Ghép sau phương hướng: 前面, 后面, 左面.","ex":"学校后面有一条河。","exPy":"Xuéxiào hòumian yǒu yì tiáo hé.","exVi":"Sau trường có một con sông.","w":"学校 后面 有 一 条 河。"}],"newChars":[],"outro":"很好！Xong bài 40."};
G.ROOMS["zh-l041"] = {"id":"zh-l041","lang":"zh","level":2,"no":41,"teacher":"wang","title":"HSK2 · Bài 41 · 左边还是右边？ Trái, phải, ở đâu","intro":["请问，商场怎么走？","Bài 41: Chỉ đường bằng 左 / 右, nói về cửa, trên đường, trên mạng, và các nơi như trung tâm thương mại, hiệu thuốc, khách sạn. Bấm 1 · Học để bắt đầu."],"introPy":"Qǐngwèn, shāngchǎng zěnme zǒu?","gram":{"t":"往 + phương hướng + động từ","b":"往左走 · 往右拐 · 往前走","d":"Chỉ đường: 往 nghĩa là \"về phía\". Câu chỉ đường điển hình: 一直往前走，然后往右拐.","ex":[["一直往前走，然后往左拐。","Đi thẳng về phía trước, rồi rẽ trái.","Yìzhí wǎng qián zǒu, ránhòu wǎng zuǒ guǎi."],["药店在路的右边。","Hiệu thuốc ở bên phải đường.","Yàodiàn zài lù de yòubian."]]},"grams":[{"t":"往 + phương hướng + động từ","b":"往左走 · 往右拐 · 往前走","d":"Chỉ đường: 往 nghĩa là \"về phía\". Câu chỉ đường điển hình: 一直往前走，然后往右拐.","ex":[["一直往前走，然后往左拐。","Đi thẳng về phía trước, rồi rẽ trái.","Yìzhí wǎng qián zǒu, ránhòu wǎng zuǒ guǎi."],["药店在路的右边。","Hiệu thuốc ở bên phải đường.","Yàodiàn zài lù de yòubian."]]},{"t":"在 + nơi chốn + động từ","b":"在网上买 · 在门口等 · 在路上吃","d":"Nơi diễn ra hành động đứng TRƯỚC động từ, với 在.","ex":[["我们在门口见吧。","Mình gặp nhau ở cổng nhé.","Wǒmen zài ménkǒu jiàn ba."],["他在路上吃早饭。","Anh ấy ăn sáng trên đường đi.","Tā zài lùshang chī zǎofàn."]]}],"items":[{"zh":"左","py":"zuǒ","vi":"bên trái","hv":"tả","note":"\"Tả\" trong \"tả hữu\". Hay dùng 左边.","ex":"左边是药店，右边是书店。","exPy":"Zuǒbian shì yàodiàn, yòubian shì shūdiàn.","exVi":"Bên trái là hiệu thuốc, bên phải là hiệu sách.","w":"左边 是 药店， 右边 是 书店。"},{"zh":"右","py":"yòu","vi":"bên phải","hv":"hữu","note":"\"Hữu\" trong \"tả hữu\". 右边 là bên phải.","ex":"银行在右边。","exPy":"Yínháng zài yòubian.","exVi":"Ngân hàng ở bên phải.","w":"银行 在 右边。"},{"zh":"门口","py":"ménkǒu","vi":"cổng, trước cửa","hv":"môn khẩu","note":"门 (cửa) + 口 (miệng, lối vào).","ex":"我在学校门口等你。","exPy":"Wǒ zài xuéxiào ménkǒu děng nǐ.","exVi":"Tôi đợi bạn ở cổng trường.","w":"我 在 学校 门口 等 你。"},{"zh":"路上","py":"lùshang","vi":"trên đường, dọc đường","hv":"lộ thượng","note":"Nói khi đang di chuyển: 我在路上 (tôi đang trên đường tới).","ex":"我已经在路上了，十分钟到。","exPy":"Wǒ yǐjīng zài lùshang le, shí fēnzhōng dào.","exVi":"Tôi đang trên đường rồi, mười phút nữa tới.","w":"我 已经 在 路上 了， 十分 钟 到。"},{"zh":"网上","py":"wǎngshang","vi":"trên mạng","hv":"võng thượng","note":"网 = \"võng\" (lưới), nghĩa mới là mạng internet.","ex":"现在很多人在网上买东西。","exPy":"Xiànzài hěn duō rén zài wǎngshang mǎi dōngxi.","exVi":"Bây giờ rất nhiều người mua đồ trên mạng.","w":"现在 很 多 人 在 网上 买 东西。"},{"zh":"商场","py":"shāngchǎng","vi":"trung tâm thương mại","hv":"thương trường","note":"Chính là \"thương trường\" nhưng nghĩa cụ thể là toà nhà mua sắm lớn.","ex":"请问，商场怎么走？","exPy":"Qǐngwèn, shāngchǎng zěnme zǒu?","exVi":"Cho hỏi, đến trung tâm thương mại đi thế nào?","w":"请问， 商场 怎么 走？"},{"zh":"药店","py":"yàodiàn","vi":"hiệu thuốc","hv":"dược điếm","note":"药 (thuốc, \"dược\") + 店.","ex":"前面有一家药店。","exPy":"Qiánmian yǒu yì jiā yàodiàn.","exVi":"Phía trước có một hiệu thuốc.","w":"前面 有 一 家 药店。"},{"zh":"酒店","py":"jiǔdiàn","vi":"khách sạn","hv":"tửu điếm","note":"Nghĩa gốc là quán rượu, nay chủ yếu là khách sạn.","ex":"酒店的房间很大，床也很大。","exPy":"Jiǔdiàn de fángjiān hěn dà, chuáng yě hěn dà.","exVi":"Phòng khách sạn rất rộng, giường cũng rất to.","w":"酒店 的 房间 很 大， 床 也 很 大。"},{"zh":"床","py":"chuáng","vi":"cái giường","hv":"sàng","note":"\"Sàng\" trong \"long sàng\" (giường vua). 起床 là rời giường.","ex":"我的床很舒服。","exPy":"Wǒ de chuáng hěn shūfu.","exVi":"Giường của tôi rất êm.","w":"我 的 床 很 舒服。"},{"zh":"间","py":"jiān","vi":"gian, phòng (lượng từ)","hv":"gian","note":"\"Gian\" trong \"không gian\", \"gian phòng\". Đếm phòng: 一间房间.","ex":"这个房子有三间房间。","exPy":"Zhège fángzi yǒu sān jiān fángjiān.","exVi":"Căn nhà này có ba phòng.","w":"这个 房子 有 三 间 房间。"}],"newChars":["口","网","酒"],"outro":"很好！Xong bài 41."};
G.ROOMS["zh-l042"] = {"id":"zh-l042","lang":"zh","level":2,"no":42,"teacher":"wang","title":"HSK2 · Bài 42 · 红茶还是绿茶？ Màu sắc và đồ uống","intro":["服务员，我要一杯奶茶。","Bài 42: Gọi tên màu bằng 色, chọn đồ uống trà đỏ, trà xanh, trà sữa, và nói về món thịt. Bấm 1 · Học để bắt đầu."],"introPy":"Fúwùyuán, wǒ yào yì bēi nǎichá.","gram":{"t":"Màu + 的 + danh từ","b":"红色的衣服 · 黑色的车","d":"Màu sắc đứng trước danh từ, thường có 的. Nói ngắn có thể bỏ 色: 红衣服, 白车.","ex":[["我想买一辆白色的车。","Tôi muốn mua một chiếc xe màu trắng.","Wǒ xiǎng mǎi yí liàng báisè de chē."],["那件黑色的衣服是谁的？","Bộ đồ màu đen kia là của ai?","Nà jiàn hēisè de yīfu shì shéi de?"]]},"grams":[{"t":"Màu + 的 + danh từ","b":"红色的衣服 · 黑色的车","d":"Màu sắc đứng trước danh từ, thường có 的. Nói ngắn có thể bỏ 色: 红衣服, 白车.","ex":[["我想买一辆白色的车。","Tôi muốn mua một chiếc xe màu trắng.","Wǒ xiǎng mǎi yí liàng báisè de chē."],["那件黑色的衣服是谁的？","Bộ đồ màu đen kia là của ai?","Nà jiàn hēisè de yīfu shì shéi de?"]]},{"t":"A 还是 B: hỏi chọn một","b":"Động từ + A + 还是 + B？","d":"Câu hỏi lựa chọn dùng 还是, không thêm 吗 ở cuối.","ex":[["你喝红茶还是绿茶？","Bạn uống trà đen hay trà xanh?","Nǐ hē hóngchá háishi lǜchá?"],["你喜欢红色还是白色？","Bạn thích màu đỏ hay màu trắng?","Nǐ xǐhuan hóngsè háishi báisè?"]]}],"items":[{"zh":"红色","py":"hóngsè","vi":"màu đỏ","hv":"hồng sắc","note":"红 là đỏ (không phải hồng như tiếng Việt). Màu hồng là 粉色. 色 = \"sắc\" trong \"màu sắc\".","ex":"中国人结婚的时候喜欢红色。","exPy":"Zhōngguó rén jiéhūn de shíhou xǐhuan hóngsè.","exVi":"Người Trung Quốc thích màu đỏ trong đám cưới.","w":"中国 人 结婚 的 时候 喜欢 红色。"},{"zh":"白色","py":"báisè","vi":"màu trắng","hv":"bạch sắc","note":"白 = \"bạch\" trong \"bạch tuyết\".","ex":"白色和黑色，你要哪个？","exPy":"Báisè hé hēisè, nǐ yào nǎge?","exVi":"Trắng và đen, bạn lấy cái nào?","w":"白色 和 黑色， 你 要 哪个？"},{"zh":"黑色","py":"hēisè","vi":"màu đen","hv":"hắc sắc","note":"黑 = \"hắc\" trong \"hắc ám\".","ex":"我的手机是黑色的。","exPy":"Wǒ de shǒujī shì hēisè de.","exVi":"Điện thoại của tôi màu đen.","w":"我 的 手机 是 黑色 的。"},{"zh":"绿色","py":"lǜsè","vi":"màu xanh lá","hv":"lục sắc","note":"绿 = \"lục\" trong \"lục diệp\" (lá xanh). Xanh da trời là 蓝色.","ex":"春天到了，到处都是绿色。","exPy":"Chūntiān dào le, dàochù dōu shì lǜsè.","exVi":"Mùa xuân đến, khắp nơi đều xanh.","w":"春天 到 了， 到处 都 是 绿色。"},{"zh":"红茶","py":"hóngchá","vi":"trà đen","hv":"hồng trà","note":"Chú ý: tiếng Anh gọi là \"black tea\" theo màu lá, tiếng Trung gọi 红茶 theo màu nước đỏ.","ex":"我要一杯红茶。","exPy":"Wǒ yào yì bēi hóngchá.","exVi":"Tôi muốn một cốc trà đen.","w":"我 要 一 杯 红茶。"},{"zh":"绿茶","py":"lǜchá","vi":"trà xanh","hv":"lục trà","note":"Trà xanh của Việt Nam cũng là 绿茶.","ex":"早上喝一杯绿茶很舒服。","exPy":"Zǎoshang hē yì bēi lǜchá hěn shūfu.","exVi":"Buổi sáng uống một cốc trà xanh rất dễ chịu.","w":"早上 喝 一 杯 绿茶 很 舒服。"},{"zh":"奶茶","py":"nǎichá","vi":"trà sữa","hv":"nãi trà","note":"奶 (sữa) + 茶 (trà).","ex":"服务员，我要一杯奶茶。","exPy":"Fúwùyuán, wǒ yào yì bēi nǎichá.","exVi":"Phục vụ ơi, cho tôi một cốc trà sữa.","w":"服务员， 我 要 一 杯 奶茶。"},{"zh":"肉","py":"ròu","vi":"thịt","hv":"nhục","note":"\"Nhục\" trong \"nhục thể\". Thịt lợn 猪肉, thịt bò 牛肉, thịt gà 鸡肉.","ex":"这个菜里有很多肉。","exPy":"Zhège cài lǐ yǒu hěn duō ròu.","exVi":"Món này có nhiều thịt.","w":"这个 菜 里 有 很 多 肉。"}],"newChars":["绿"],"outro":"很好！Xong bài 42."};
G.ROOMS["zh-l043"] = {"id":"zh-l043","lang":"zh","level":2,"no":43,"teacher":"wang","title":"HSK2 · Bài 43 · 打车去机场 Đi lại và đi xa","intro":["我们打车去机场吧。","Bài 43: Nói về bến xe, xe buýt, gọi taxi, vé máy bay, vé vào cửa, đi bộ, bay, nước ngoài và ăn Tết. Bấm 1 · Học để bắt đầu."],"introPy":"Wǒmen dǎchē qù jīchǎng ba.","gram":{"t":"坐 / 打 / 走路: cách đi lại","b":"坐 + 公交车 / 火车 / 飞机 · 打车 · 走路","d":"Đi phương tiện công cộng dùng 坐 (ngồi), gọi taxi dùng 打车, đi bộ là 走路. Cách đi đứng trước động từ chính: 坐公交车上班.","ex":[["我坐飞机去北京。","Tôi đi máy bay đến Bắc Kinh.","Wǒ zuò fēijī qù Běijīng."],["他走路去学校。","Cậu ấy đi bộ đến trường.","Tā zǒulù qù xuéxiào."]]},"grams":[{"t":"坐 / 打 / 走路: cách đi lại","b":"坐 + 公交车 / 火车 / 飞机 · 打车 · 走路","d":"Đi phương tiện công cộng dùng 坐 (ngồi), gọi taxi dùng 打车, đi bộ là 走路. Cách đi đứng trước động từ chính: 坐公交车上班.","ex":[["我坐飞机去北京。","Tôi đi máy bay đến Bắc Kinh.","Wǒ zuò fēijī qù Běijīng."],["他走路去学校。","Cậu ấy đi bộ đến trường.","Tā zǒulù qù xuéxiào."]]},{"t":"离: khoảng cách","b":"A + 离 + B + 远 / 近","d":"Nói A cách B xa hay gần. 离 đứng trước điểm mốc.","ex":[["机场离这儿很远。","Sân bay cách đây rất xa.","Jīchǎng lí zhèr hěn yuǎn."],["我家离学校很近。","Nhà tôi cách trường rất gần.","Wǒ jiā lí xuéxiào hěn jìn."]]}],"items":[{"zh":"车站","py":"chēzhàn","vi":"bến xe, ga","hv":"xa trạm","note":"车 + 站 (trạm). Ga tàu là 火车站.","ex":"请问，去车站坐几路公交车？","exPy":"Qǐngwèn, qù chēzhàn zuò jǐ lù gōngjiāochē?","exVi":"Cho hỏi, ra bến xe thì đi xe buýt số mấy?","w":"请问， 去 车站 坐 几 路 公交车？"},{"zh":"公交车","py":"gōngjiāochē","vi":"xe buýt","hv":"công giao xa","note":"公 (công cộng) + 交 (giao thông) + 车. Cũng nói 公共汽车.","ex":"我每天坐公交车上班。","exPy":"Wǒ měi tiān zuò gōngjiāochē shàngbān.","exVi":"Ngày nào tôi cũng đi xe buýt đi làm.","w":"我 每 天 坐 公交车 上班。"},{"zh":"打车","py":"dǎchē","vi":"gọi taxi, bắt xe","hv":"đả xa","note":"打 ở đây là \"gọi, đón\". Gọi xe qua ứng dụng cũng là 打车.","ex":"我们打车去机场吧。","exPy":"Wǒmen dǎchē qù jīchǎng ba.","exVi":"Mình gọi taxi ra sân bay nhé.","w":"我们 打车 去 机场 吧。"},{"zh":"走路","py":"zǒulù","vi":"đi bộ","hv":"tẩu lộ","note":"走 (đi) + 路 (đường).","ex":"我家很近，走路十分钟。","exPy":"Wǒ jiā hěn jìn, zǒulù shí fēnzhōng.","exVi":"Nhà tôi gần lắm, đi bộ mười phút.","w":"我 家 很 近， 走路 十分 钟。"},{"zh":"飞","py":"fēi","vi":"bay","hv":"phi","note":"\"Phi\" trong \"phi cơ\", \"phi công\". Máy bay là 飞机.","ex":"飞机飞得很快。","exPy":"Fēijī fēi de hěn kuài.","exVi":"Máy bay bay rất nhanh.","w":"飞机 飞 得 很 快。"},{"zh":"机票","py":"jīpiào","vi":"vé máy bay","hv":"cơ phiếu","note":"机 (máy bay) + 票 (vé, \"phiếu\").","ex":"过年的时候机票很贵。","exPy":"Guònián de shíhou jīpiào hěn guì.","exVi":"Dịp Tết vé máy bay rất đắt.","w":"过年 的 时候 机票 很 贵。"},{"zh":"门票","py":"ménpiào","vi":"vé vào cửa","hv":"môn phiếu","note":"门 (cửa) + 票. Vé vào công viên, bảo tàng.","ex":"公园的门票多少钱？","exPy":"Gōngyuán de ménpiào duōshao qián?","exVi":"Vé vào công viên bao nhiêu tiền?","w":"公园 的 门票 多少 钱？"},{"zh":"外国","py":"wàiguó","vi":"nước ngoài","hv":"ngoại quốc","note":"Chính là \"ngoại quốc\". Người nước ngoài là 外国人.","ex":"很多外国人喜欢来越南过年。","exPy":"Hěn duō wàiguó rén xǐhuan lái Yuènán guònián.","exVi":"Nhiều người nước ngoài thích sang Việt Nam ăn Tết.","w":"很 多 外国 人 喜欢 来 越 南 过年。"},{"zh":"过年","py":"guònián","vi":"ăn Tết","hv":"quá niên","note":"Nghĩa đen \"qua năm\". Người Trung Quốc và người Việt đều ăn Tết âm lịch.","ex":"你回家过年吗？","exPy":"Nǐ huí jiā guònián ma?","exVi":"Bạn có về nhà ăn Tết không?","w":"你 回 家 过年 吗？"}],"newChars":["交"],"outro":"很好！Xong bài 43."};
G.ROOMS["zh-l044"] = {"id":"zh-l044","lang":"zh","level":2,"no":44,"teacher":"wang","title":"HSK2 · Bài 44 · 踢足球 Thể thao và cơ thể","intro":["我最喜欢踢足球。","Bài 44: Nói về đá bóng, chơi bóng rổ, chạy, bơi, và tay, đầu, cử động. Bấm 1 · Học để bắt đầu."],"introPy":"Wǒ zuì xǐhuan tī zúqiú.","gram":{"t":"踢 hay 打?","b":"踢 + bóng dùng chân · 打 + bóng dùng tay","d":"Đá bóng: 踢足球. Bóng rổ, bóng chuyền, cầu lông, bóng bàn: 打篮球, 打排球, 打羽毛球, 打乒乓球.","ex":[["你喜欢踢足球还是打篮球？","Bạn thích đá bóng hay chơi bóng rổ?","Nǐ xǐhuan tī zúqiú háishi dǎ lánqiú?"],["我们下午打羽毛球吧。","Chiều nay mình đánh cầu lông nhé.","Wǒmen xiàwǔ dǎ yǔmáoqiú ba."]]},"grams":[{"t":"踢 hay 打?","b":"踢 + bóng dùng chân · 打 + bóng dùng tay","d":"Đá bóng: 踢足球. Bóng rổ, bóng chuyền, cầu lông, bóng bàn: 打篮球, 打排球, 打羽毛球, 打乒乓球.","ex":[["你喜欢踢足球还是打篮球？","Bạn thích đá bóng hay chơi bóng rổ?","Nǐ xǐhuan tī zúqiú háishi dǎ lánqiú?"],["我们下午打羽毛球吧。","Chiều nay mình đánh cầu lông nhé.","Wǒmen xiàwǔ dǎ yǔmáoqiú ba."]]},{"t":"Động từ + 得 + đánh giá","b":"跑得很快 · 踢得很好","d":"Nhận xét một hành động: đặt 得 sau động từ, rồi tính từ. Phủ định đặt 不 sau 得: 跑得不快.","ex":[["她游得很好。","Cô ấy bơi rất giỏi.","Tā yóu de hěn hǎo."],["我踢得不好。","Tôi đá không giỏi.","Wǒ tī de bù hǎo."]]}],"items":[{"zh":"球","py":"qiú","vi":"quả bóng; bóng (môn chơi)","hv":"cầu","note":"\"Cầu\" trong \"địa cầu\", \"bóng đá\" tiếng Việt cũ là \"túc cầu\".","ex":"我最喜欢踢足球。","exPy":"Wǒ zuì xǐhuan tī zúqiú.","exVi":"Tôi thích nhất là đá bóng.","w":"我 最 喜欢 踢足球。"},{"zh":"足球","py":"zúqiú","vi":"bóng đá","hv":"túc cầu","note":"足 = chân (\"túc\"), nghĩa đen \"bóng chân\".","ex":"他是足球运动员。","exPy":"Tā shì zúqiú yùndòngyuán.","exVi":"Anh ấy là cầu thủ bóng đá.","w":"他 是 足球 运动员。"},{"zh":"篮球","py":"lánqiú","vi":"bóng rổ","hv":"lam cầu","note":"篮 = cái rổ (\"lam\").","ex":"他打篮球打得很好。","exPy":"Tā dǎ lánqiú dǎ de hěn hǎo.","exVi":"Cậu ấy chơi bóng rổ rất giỏi.","w":"他 打篮球 打 得 很 好。"},{"zh":"踢","py":"tī","vi":"đá (bằng chân)","hv":"thích","note":"Có bộ 足 (chân). Đá bóng là 踢足球.","ex":"周末我们踢足球。","exPy":"Zhōumò wǒmen tī zúqiú.","exVi":"Cuối tuần chúng tôi đá bóng.","w":"周末 我们 踢足球。"},{"zh":"打","py":"dǎ","vi":"đánh; chơi (bóng bằng tay)","hv":"đả","note":"\"Đả\" trong \"đả kích\". Chơi bóng bằng tay dùng 打: 打篮球. Cũng dùng trong 打电话.","ex":"你会打篮球吗？","exPy":"Nǐ huì dǎ lánqiú ma?","exVi":"Bạn biết chơi bóng rổ không?","w":"你 会 打篮球 吗？"},{"zh":"跑","py":"pǎo","vi":"chạy","hv":"bào","note":"Có bộ 足. Chạy bộ là 跑步.","ex":"他每天早上跑步。","exPy":"Tā měi tiān zǎoshang pǎobù.","exVi":"Sáng nào anh ấy cũng chạy bộ.","w":"他 每 天 早上 跑步。"},{"zh":"游","py":"yóu","vi":"bơi","hv":"du","note":"\"Du\" trong \"du lịch\", \"du thuyền\". Bơi lội là 游泳.","ex":"天气热，我们去游泳吧。","exPy":"Tiānqì rè, wǒmen qù yóuyǒng ba.","exVi":"Trời nóng, mình đi bơi nhé.","w":"天气 热， 我们 去 游泳 吧。"},{"zh":"手","py":"shǒu","vi":"tay","hv":"thủ","note":"\"Thủ\" trong \"thủ công\", \"cao thủ\". Điện thoại 手机 là \"máy cầm tay\".","ex":"你的手怎么了？","exPy":"Nǐ de shǒu zěnme le?","exVi":"Tay bạn sao thế?","w":"你 的 手 怎么 了？"},{"zh":"头","py":"tóu","vi":"đầu","hv":"đầu","note":"Chính là \"đầu\" tiếng Việt. Đau đầu là 头疼.","ex":"我头有点儿疼。","exPy":"Wǒ tóu yǒudiǎnr téng.","exVi":"Tôi hơi đau đầu.","w":"我 头 有点儿 疼。"},{"zh":"动","py":"dòng","vi":"cử động, động đậy","hv":"động","note":"\"Động\" trong \"vận động\", \"hoạt động\". 别动 là \"đừng động đậy\".","ex":"别动，我给你拍张照片。","exPy":"Bié dòng, wǒ gěi nǐ pāi zhāng zhàopiàn.","exVi":"Đừng động đậy, tôi chụp cho bạn tấm ảnh.","w":"别 动， 我 给 你 拍 张 照片。"}],"newChars":["头"],"outro":"很好！Xong bài 44."};
G.ROOMS["zh-l045"] = {"id":"zh-l045","lang":"zh","level":2,"no":45,"teacher":"wang","title":"HSK2 · Bài 45 · 开学了 Vào năm học","intro":["明天开学，我很高兴。","Bài 45: Nói về đồ dùng học tập, từ mới, thi cử, ngày khai giảng, cấp ba, và ghi họ tên. Bấm 1 · Học để bắt đầu."],"introPy":"Míngtiān kāixué, wǒ hěn gāoxìng.","gram":{"t":"忘了 / 别忘了","b":"忘了 + việc · 别忘了 + việc","d":"忘了 là đã quên. Nhắc ai đừng quên thì nói 别忘了.","ex":[["别忘了带书包。","Đừng quên mang cặp sách.","Bié wàng le dài shūbāo."],["我忘了带笔。","Tôi quên mang bút.","Wǒ wàng le dài bǐ."]]},"grams":[{"t":"忘了 / 别忘了","b":"忘了 + việc · 别忘了 + việc","d":"忘了 là đã quên. Nhắc ai đừng quên thì nói 别忘了.","ex":[["别忘了带书包。","Đừng quên mang cặp sách.","Bié wàng le dài shūbāo."],["我忘了带笔。","Tôi quên mang bút.","Wǒ wàng le dài bǐ."]]},{"t":"考 + môn / kỳ thi","b":"考汉语 · 考大学 · 考得好","d":"考 đi thẳng với tên môn hay kỳ thi. Nhận xét kết quả dùng 得: 考得很好.","ex":[["你这次考得怎么样？","Lần này bạn thi thế nào?","Nǐ zhè cì kǎo de zěnmeyàng?"],["他想考北京大学。","Cậu ấy muốn thi vào Đại học Bắc Kinh.","Tā xiǎng kǎo Běijīng Dàxué."]]}],"items":[{"zh":"开学","py":"kāixué","vi":"khai giảng, vào năm học","hv":"khai học","note":"开 = mở, bắt đầu. \"Khai giảng\" tiếng Việt cùng chữ 开.","ex":"明天开学，我很高兴。","exPy":"Míngtiān kāixué, wǒ hěn gāoxìng.","exVi":"Mai khai giảng, tôi rất vui.","w":"明天 开学， 我 很 高兴。"},{"zh":"高中","py":"gāozhōng","vi":"trung học phổ thông, cấp ba","hv":"cao trung","note":"Cấp ba là 高中, cấp hai là 初中.","ex":"高中生每天学习很多东西。","exPy":"Gāozhōngshēng měi tiān xuéxí hěn duō dōngxi.","exVi":"Học sinh cấp ba ngày nào cũng học rất nhiều.","w":"高中 生 每 天 学习 很 多 东西。"},{"zh":"书包","py":"shūbāo","vi":"cặp sách","hv":"thư bao","note":"书 (sách) + 包 (túi, \"bao\").","ex":"我的书包很重。","exPy":"Wǒ de shūbāo hěn zhòng.","exVi":"Cặp sách của tôi rất nặng.","w":"我 的 书包 很 重。"},{"zh":"本子","py":"běnzi","vi":"quyển vở","hv":"bản tử","note":"本 = \"bản\" trong \"bản sao\". Đếm vở và sách bằng 本.","ex":"我把生词写在本子上。","exPy":"Wǒ bǎ shēngcí xiě zài běnzi shang.","exVi":"Tôi viết từ mới vào vở.","w":"我 把 生 词 写 在 本子 上。"},{"zh":"笔","py":"bǐ","vi":"cây bút","hv":"bút","note":"Chính là \"bút\". Có bộ ⺮ (tre): bút xưa làm từ tre.","ex":"你有笔吗？借我用一下。","exPy":"Nǐ yǒu bǐ ma? Jiè wǒ yòng yíxià.","exVi":"Bạn có bút không? Cho tôi mượn chút.","w":"你 有 笔 吗？ 借 我 用 一下。"},{"zh":"词","py":"cí","vi":"từ (ngôn ngữ)","hv":"từ","note":"\"Từ\" trong \"từ điển\", \"từ vựng\". Từ mới là 生词.","ex":"这个词是什么意思？","exPy":"Zhège cí shì shénme yìsi?","exVi":"Từ này nghĩa là gì?","w":"这个 词 是 什么 意思？"},{"zh":"考","py":"kǎo","vi":"thi, kiểm tra","hv":"khảo","note":"\"Khảo\" trong \"khảo thí\". Thi HSK: 考HSK.","ex":"考试的时候不要忘了写姓名。","exPy":"Kǎoshì de shíhou búyào wàng le xiě xìngmíng.","exVi":"Lúc thi đừng quên ghi họ tên.","w":"考试 的 时候 不要 忘 了 写 姓名。"},{"zh":"忘","py":"wàng","vi":"quên","hv":"vong","note":"Trên là 亡 (mất), dưới là 心 (lòng): mất khỏi lòng là quên. Hay dùng 忘了.","ex":"对不起，我忘了你的名字。","exPy":"Duìbuqǐ, wǒ wàng le nǐ de míngzi.","exVi":"Xin lỗi, tôi quên tên bạn rồi.","w":"对不起， 我 忘 了 你 的 名字。"},{"zh":"姓名","py":"xìngmíng","vi":"họ tên","hv":"tính danh","note":"姓 (họ) + 名 (tên). Hay gặp trên các mẫu đơn.","ex":"请写一下你的姓名。","exPy":"Qǐng xiě yíxià nǐ de xìngmíng.","exVi":"Xin hãy viết họ tên của bạn.","w":"请 写 一下 你 的 姓名。"},{"zh":"名","py":"míng","vi":"tên; hạng (lượng từ)","hv":"danh","note":"\"Danh\" trong \"danh sách\". Làm lượng từ cho thứ hạng, người: 第一名 (hạng nhất).","ex":"这次考试他考了第二名。","exPy":"Zhè cì kǎoshì tā kǎo le dì èr míng.","exVi":"Kỳ thi này cậu ấy được hạng hai.","w":"这 次 考试 他 考 了 第 二 名。"}],"newChars":["包","词","忘"],"outro":"很好！Xong bài 45."};
G.ROOMS["zh-l046"] = {"id":"zh-l046","lang":"zh","level":2,"no":46,"teacher":"wang","title":"HSK2 · Bài 46 · 小时候 Hồi nhỏ và bây giờ","intro":["小时候我很喜欢唱歌。","Bài 46: Nói về trẻ con, hồi nhỏ, từ nhỏ, tuần, đôi khi, và các trạng thái 已经 / 快要 / 正. Bấm 1 · Học để bắt đầu."],"introPy":"Xiǎoshíhou wǒ hěn xǐhuan chànggē.","gram":{"t":"已经…了 / 快要…了","b":"已经 + động từ + 了 · 快要 + động từ + 了","d":"Hai cấu trúc đối xứng: việc đã xong và việc sắp xảy ra. Cả hai đều có 了 ở cuối.","ex":[["我已经吃饭了。","Tôi ăn cơm rồi.","Wǒ yǐjīng chīfàn le."],["快要下雨了，我们快走吧。","Sắp mưa rồi, mình đi nhanh thôi.","Kuàiyào xià yǔ le, wǒmen kuài zǒu ba."]]},"grams":[{"t":"已经…了 / 快要…了","b":"已经 + động từ + 了 · 快要 + động từ + 了","d":"Hai cấu trúc đối xứng: việc đã xong và việc sắp xảy ra. Cả hai đều có 了 ở cuối.","ex":[["我已经吃饭了。","Tôi ăn cơm rồi.","Wǒ yǐjīng chīfàn le."],["快要下雨了，我们快走吧。","Sắp mưa rồi, mình đi nhanh thôi.","Kuàiyào xià yǔ le, wǒmen kuài zǒu ba."]]},{"t":"正 + động từ + 呢: đang làm","b":"正 / 正在 + động từ + 呢","d":"Diễn tả việc đang diễn ra đúng lúc đó. Hay dùng khi trả lời điện thoại.","ex":[["他正上课呢，不能接电话。","Anh ấy đang học, không nghe điện thoại được.","Tā zhèng shàngkè ne, bù néng jiē diànhuà."],["你打电话的时候，我正睡觉呢。","Lúc bạn gọi, tôi đang ngủ.","Nǐ dǎ diànhuà de shíhou, wǒ zhèng shuìjiào ne."]]}],"items":[{"zh":"小孩儿","py":"xiǎoháir","vi":"trẻ con","hv":"tiểu hài nhi","note":"小 + 孩 (\"hài\" trong \"hài nhi\"). Khẩu ngữ, hay đọc uốn lưỡi.","ex":"那个小孩儿很可爱。","exPy":"Nàge xiǎoháir hěn kě'ài.","exVi":"Đứa trẻ kia rất đáng yêu.","w":"那个 小孩儿 很 可爱。"},{"zh":"男孩儿","py":"nánháir","vi":"bé trai, cậu bé","hv":"nam hài nhi","note":"男 + 孩儿. Cũng nói 男孩子.","ex":"他们有一个男孩儿。","exPy":"Tāmen yǒu yí ge nánháir.","exVi":"Họ có một bé trai.","w":"他们 有 一 个 男孩儿。"},{"zh":"女孩儿","py":"nǚháir","vi":"bé gái, cô bé","hv":"nữ hài nhi","note":"女 + 孩儿. Cũng dùng gọi cô gái trẻ.","ex":"那个女孩儿是我同学。","exPy":"Nàge nǚháir shì wǒ tóngxué.","exVi":"Cô gái kia là bạn cùng lớp tôi.","w":"那个 女孩儿 是 我 同学。"},{"zh":"小时候","py":"xiǎoshíhou","vi":"hồi nhỏ","hv":"tiểu thời hậu","note":"小 (nhỏ) + 时候 (lúc). Kể chuyện ngày bé luôn mở đầu bằng 小时候.","ex":"小时候我很喜欢唱歌。","exPy":"Xiǎoshíhou wǒ hěn xǐhuan chànggē.","exVi":"Hồi nhỏ tôi rất thích hát.","w":"小时候 我 很 喜欢 唱歌。"},{"zh":"从小","py":"cóngxiǎo","vi":"từ nhỏ","hv":"tòng tiểu","note":"从 (từ) + 小. Đứng trước động từ: 从小就喜欢.","ex":"我从小就想当老师。","exPy":"Wǒ cóngxiǎo jiù xiǎng dāng lǎoshī.","exVi":"Từ nhỏ tôi đã muốn làm giáo viên.","w":"我 从小 就 想 当 老师。"},{"zh":"时","py":"shí","vi":"lúc, khi","hv":"thời","note":"Dạng viết gọn của 时候: 上课时 = 上课的时候.","ex":"这个周末你有时间吗？","exPy":"Zhège zhōumò nǐ yǒu shíjiān ma?","exVi":"Cuối tuần này bạn có thời gian không?","w":"这个 周末 你 有时 间 吗？"},{"zh":"有时","py":"yǒushí","vi":"đôi khi, có lúc","hv":"hữu thời","note":"Gọn hơn 有时候, nghĩa như nhau.","ex":"我有时坐公交车，有时走路。","exPy":"Wǒ yǒushí zuò gōngjiāochē, yǒushí zǒulù.","exVi":"Tôi lúc đi xe buýt, lúc đi bộ.","w":"我 有时 坐 公交车， 有时 走路。"},{"zh":"周","py":"zhōu","vi":"tuần","hv":"chu","note":"Trang trọng hơn 星期. 周末 là cuối tuần, 周一 là thứ Hai.","ex":"我们下周去旅游。","exPy":"Wǒmen xià zhōu qù lǚyóu.","exVi":"Tuần sau chúng tôi đi du lịch.","w":"我们 下 周 去 旅游。"},{"zh":"已经","py":"yǐjīng","vi":"đã, rồi","hv":"dĩ kinh","note":"\"Dĩ\" trong \"dĩ vãng\". Thường đi với 了 ở cuối câu: 已经…了.","ex":"我已经学了一年汉语了。","exPy":"Wǒ yǐjīng xué le yì nián Hànyǔ le.","exVi":"Tôi đã học tiếng Trung được một năm rồi.","w":"我 已经 学 了 一 年 汉语 了。"},{"zh":"快要","py":"kuàiyào","vi":"sắp, sắp sửa","hv":"khoái yếu","note":"快要…了 là \"sắp…rồi\". Không đi với mốc thời gian cụ thể.","ex":"快要过年了，大家都很高兴。","exPy":"Kuàiyào guònián le, dàjiā dōu hěn gāoxìng.","exVi":"Sắp Tết rồi, ai cũng rất vui.","w":"快要 过年 了， 大家 都 很 高兴。"},{"zh":"正","py":"zhèng","vi":"đang (đúng lúc)","hv":"chính","note":"\"Chính\" trong \"chính lúc\". 正在 cũng là \"đang\". Hay đi với 呢 ở cuối.","ex":"我正吃饭呢。","exPy":"Wǒ zhèng chīfàn ne.","exVi":"Tôi đang ăn cơm đây.","w":"我 正 吃 饭 呢。"}],"newChars":["周","已","经"],"outro":"很好！Xong bài 46."};
G.ROOMS["zh-l047"] = {"id":"zh-l047","lang":"zh","level":2,"no":47,"teacher":"wang","title":"HSK2 · Bài 47 · 不好意思 Nói chuyện tự nhiên","intro":["不好意思，请问这个怎么用？","Bài 47: Khen, xin lỗi nhẹ nhàng, nói thú vị hay chán, dùng 这么 / 那么 / 这样 / 那样, nhờ giúp, và nối câu bằng 但. Bấm 1 · Học để bắt đầu."],"introPy":"Bù hǎoyìsi, qǐngwèn zhège zěnme yòng?","gram":{"t":"这么 / 那么 + tính từ","b":"这么 + 好 / 贵 / 冷 · 没有 + A + 那么 + tính từ","d":"这么 cho thứ ở gần hoặc đang nói tới, 那么 cho thứ ở xa. 那么 còn dùng để so sánh: 我没有他那么高 (tôi không cao bằng anh ấy).","ex":[["你的房间这么大！","Phòng bạn rộng thế!","Nǐ de fángjiān zhème dà!"],["我没有你那么忙。","Tôi không bận bằng bạn.","Wǒ méiyǒu nǐ nàme máng."]]},"grams":[{"t":"这么 / 那么 + tính từ","b":"这么 + 好 / 贵 / 冷 · 没有 + A + 那么 + tính từ","d":"这么 cho thứ ở gần hoặc đang nói tới, 那么 cho thứ ở xa. 那么 còn dùng để so sánh: 我没有他那么高 (tôi không cao bằng anh ấy).","ex":[["你的房间这么大！","Phòng bạn rộng thế!","Nǐ de fángjiān zhème dà!"],["我没有你那么忙。","Tôi không bận bằng bạn.","Wǒ méiyǒu nǐ nàme máng."]]},{"t":"帮 + người + động từ","b":"帮我买 · 帮他拿 · 帮妈妈做饭","d":"Người được giúp đứng ngay sau 帮, rồi đến việc cần làm.","ex":[["你帮我买一杯咖啡吧。","Bạn mua giúp tôi một cốc cà phê nhé.","Nǐ bāng wǒ mǎi yì bēi kāfēi ba."],["我帮妈妈做饭。","Tôi giúp mẹ nấu cơm.","Wǒ bāng māma zuò fàn."]]}],"items":[{"zh":"不错","py":"búcuò","vi":"khá tốt, không tồi","hv":"bất thác","note":"Nghĩa đen \"không sai\", dùng để khen nhẹ. Người Trung Quốc khen bằng 不错 rất nhiều.","ex":"这家饭店的菜很不错。","exPy":"Zhè jiā fàndiàn de cài hěn búcuò.","exVi":"Món ăn của nhà hàng này khá ngon.","w":"这 家 饭店 的 菜 很 不错。"},{"zh":"不好意思","py":"bù hǎoyìsi","vi":"ngại quá, xin lỗi","hv":"bất hảo ý tứ","note":"Nhẹ hơn 对不起. Dùng khi làm phiền, nhờ vả, hoặc thấy ngại.","ex":"不好意思，请问这个怎么用？","exPy":"Bù hǎoyìsi, qǐngwèn zhège zěnme yòng?","exVi":"Ngại quá, cho hỏi cái này dùng thế nào?","w":"不好意思， 请问 这个 怎么 用？"},{"zh":"有意思","py":"yǒu yìsi","vi":"thú vị, hay","hv":"hữu ý tứ","note":"意思 là \"ý nghĩa\". Có ý nghĩa thì thú vị.","ex":"学汉语很有意思，但不容易。","exPy":"Xué Hànyǔ hěn yǒu yìsi, dàn bù róngyì.","exVi":"Học tiếng Trung rất thú vị, nhưng không dễ.","w":"学 汉语 很 有意思， 但 不容 易。"},{"zh":"没意思","py":"méi yìsi","vi":"chán, vô vị","hv":"một ý tứ","note":"Đối lập với 有意思.","ex":"这个电影太没意思了。","exPy":"Zhège diànyǐng tài méi yìsi le.","exVi":"Bộ phim này chán quá.","w":"这个 电影 太 没意思 了。"},{"zh":"这么","py":"zhème","vi":"như thế này, đến vậy","hv":"giá ma","note":"Đứng trước tính từ để nhấn mạnh: 这么贵 (đắt thế này).","ex":"你怎么这么高兴？","exPy":"Nǐ zěnme zhème gāoxìng?","exVi":"Sao bạn vui thế?","w":"你 怎么 这么 高兴？"},{"zh":"那么","py":"nàme","vi":"như thế kia; vậy thì","hv":"na ma","note":"Trước tính từ là \"như thế\"; đầu câu là \"vậy thì\".","ex":"那么，我们明天见吧。","exPy":"Nàme, wǒmen míngtiān jiàn ba.","exVi":"Vậy thì, mai mình gặp nhé.","w":"那么， 我们 明天 见 吧。"},{"zh":"这样","py":"zhèyàng","vi":"như thế này, cách này","hv":"giá dạng","note":"样 = \"dạng\" trong \"hình dạng\". 这样做 là \"làm như thế này\".","ex":"别这样，我们是朋友。","exPy":"Bié zhèyàng, wǒmen shì péngyou.","exVi":"Đừng thế, chúng ta là bạn mà.","w":"别 这样， 我们 是 朋友。"},{"zh":"那样","py":"nàyàng","vi":"như thế kia, cách kia","hv":"na dạng","note":"Đối xứng với 这样.","ex":"别那样说，他会不高兴的。","exPy":"Bié nàyàng shuō, tā huì bù gāoxìng de.","exVi":"Đừng nói như thế, anh ấy sẽ buồn đấy.","w":"别 那样 说， 他 会 不 高兴 的。"},{"zh":"帮","py":"bāng","vi":"giúp","hv":"bang","note":"\"Bang\" trong \"bang trợ\". Gọn hơn 帮助, rất hay dùng trong khẩu ngữ.","ex":"你能帮我一下吗？","exPy":"Nǐ néng bāng wǒ yíxià ma?","exVi":"Bạn giúp tôi một chút được không?","w":"你 能 帮 我 一下 吗？"},{"zh":"但","py":"dàn","vi":"nhưng","hv":"đãn","note":"Gọn hơn 但是, nghĩa như nhau.","ex":"这件衣服很好看，但有点儿贵。","exPy":"Zhè jiàn yīfu hěn hǎokàn, dàn yǒudiǎnr guì.","exVi":"Bộ quần áo này đẹp, nhưng hơi đắt.","w":"这 件 衣服 很 好看， 但 有点儿 贵。"}],"newChars":[],"outro":"很好！Xong bài 47."};
G.ZH_LOADED = G.ZH_LOADED || {}; G.ZH_LOADED["data/zh_c2.js"] = 1;
